#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub(crate) enum DowngradeRepresentation {
    Recorded,
    LinearCompaction,
}

impl DowngradeRepresentation {
    pub(crate) fn parse(value: &str) -> Result<Self, OrgraftError> {
        match value {
            "recorded" => Ok(Self::Recorded),
            "linear-compaction" => Ok(Self::LinearCompaction),
            _ => Err(adopt_error(format!(
                "invalid downgrade representation `{value}`; expected recorded or linear-compaction"
            ))),
        }
    }

    pub(crate) fn as_str(self) -> &'static str {
        match self {
            Self::Recorded => "recorded",
            Self::LinearCompaction => "linear-compaction",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum IntraMeasurement {
    ExactCore,
    FullCopy,
}

impl IntraMeasurement {
    pub(crate) fn parse(value: &str) -> Result<Self, OrgraftError> {
        match value {
            "exact-core" => Ok(Self::ExactCore),
            "full-copy" => Ok(Self::FullCopy),
            _ => Err(adopt_error(format!(
                "invalid intra measurement `{value}`; expected exact-core or full-copy"
            ))),
        }
    }

    pub(crate) fn as_str(self) -> &'static str {
        match self {
            Self::ExactCore => "exact-core",
            Self::FullCopy => "full-copy",
        }
    }
}

