        assert_eq!(full.len(), 1);
        assert_eq!([full[0].p1, full[0].p2, full[0].p3, full[0].p4], [1, 2, 1, 0]);
        assert_eq!(full[0].support_reads, BTreeSet::from([
            "literal|canonical".into(), "literal|full2".into(), "literal|boundary25".into(), "literal|full3".into()]));
        let default = measure(&[family.clone()], IntraMeasurement::ExactCore);
        assert_eq!([default[0].p1, default[0].p2, default[0].p3, default[0].p4], [1, 0, 0, 0]);
        let mut duplicate = family.clone();
