    #[test]
    fn cross_coordinate_handoff_checks_indels_bases_boundaries_and_orientation() {
        let target = "AAAACCGGTTACGTCCCC";
        let query = "AAAACCGG".to_string() + &"T".repeat(43) + "TTACGTCCCC";
        let line = format!("q\t{}\t0\t{}\t+\tt\t{}\t0\t{}\t{}\t{}\t60\tcg:Z:8=43I10=",
            query.len(), query.len(), target.len(), target.len(), target.len(), query.len());
        let row = parse_paf(&line).unwrap();
        assert!(cross_indel_handoff_pass(&row, &query, target, 4, 14, 4).unwrap());
        assert!(!cross_identity_alignment_pass(&row, query.len(), target.len()));
        let mut reverse = row.clone(); reverse.strand = '-';
        assert!(cross_indel_handoff_pass(&reverse, &reverse_complement(&query), target, 4, 14, 4).unwrap());
        assert!(!cross_indel_handoff_pass(&reverse, &query, target, 4, 14, 4).unwrap());
        assert!(!cross_indel_handoff_pass(&row, &query, target, 5, 14, 4).unwrap());
        let mut clipped = row.clone(); clipped.qstart = 1;
        assert!(!cross_indel_handoff_pass(&clipped, &query, target, 4, 14, 4).unwrap());
        let mut untrusted = row.clone(); untrusted.cigar = "8=43I1X9=".into();
        assert!(!cross_indel_handoff_pass(&untrusted, &query, target, 4, 14, 4).unwrap());
        let mut wrong_bases = query.clone(); wrong_bases.replace_range(5..6, "A");
        assert!(!cross_indel_handoff_pass(&row, &wrong_bases, target, 4, 14, 4).unwrap());
        let mut flank_indel = row.clone(); flank_indel.cigar = "4=43I14=".into();
        assert!(!cross_indel_handoff_pass(&flank_indel, &query, target, 4, 14, 4).unwrap());
        let deletion = parse_paf(&format!("q\t18\t0\t18\t+\tt\t61\t0\t61\t18\t61\t60\tcg:Z:8=43D10=")).unwrap();
        assert!(cross_indel_handoff_pass(&deletion, target, &query, 4, 57, 4).unwrap());
    }

