        let components: Vec<_> = [("subgraph_001", "04.polish/mito/subgraph_001/round_2/01.inputs/linear_subgraph.round_2.fasta"),
            ("subgraph_002", "04.polish/mito/subgraph_002/round_1/02.polish/polished_aln.fasta")].iter().map(|(id, fasta)| BundleComponent { source_contract: None,
                component_id: id.to_string(), gfa: fixture.join(format!("03.resolve_gfa/mito/graph/merged_unresolved_{id}.gfa")),
                component_fasta: fixture.join(fasta), validate_data_dir: None, component_reads: None, rotated_reference: None,
            }).collect();
        let graphs: Vec<_> = components.iter().map(|c| Gfa::read(&c.gfa).unwrap()).collect();
        let a = RepeatPlacement::Internal { host: "u6_u7".into(), tstart: 28393, tend: 30315, strand: '+' };
        let b = RepeatPlacement::CircleSpan { host: "u9".into(), head_end: 554, tail_start: 55319, strand: '+' };
        fs::write(work.join("repeat_families.tsv"), "repeat_family_id\tcomponent_id\tstart_0based\tend_0based_exclusive\tstrand\nrepeat_0004\tsubgraph_001\t147057\t148936\t+\nrepeat_0004\tsubgraph_002\t33769\t35648\t+\n").unwrap();
        let decision = AdoptDecision { component_id: "subgraph_001|subgraph_002".into(), canonical_id: "inter_repeat_0004".into(), current_class: "intercomponent_non_graph_repeat".into(), decision: "adopt_upgrade_cross_component".into(), note: "".into(), repeat_length_bp: 1879 };
        let mut repeat_inputs = String::new();
