    #[test]
    fn cross_recorded_splice_preserves_repeat_occurrences_and_source_junctions() {
        let source = |nodes: &[(&str, &str)], links: Vec<Link>| Gfa { headers: Vec::new(),
            segments: nodes.iter().map(|(n,s)| ((*n).into(),new_segment(n,(*s).into(),"test"))).collect(),
            order: nodes.iter().map(|(n,_)| (*n).into()).collect(), links, other_lines: Vec::new() };
        let a = source_walk_fixture(source(&[("h","AAAACCCCGGGG"),("v","ATAT"),("U","GGTT")],
            vec![lk("h",'-',"U",'+'),lk("U",'+',"v",'-'),lk("v",'-',"U",'+'),lk("U",'+',"h",'-')]),
            &[("h",true),("U",false),("v",true),("U",false)],true);
        let b = source_walk_fixture(source(&[("b","TTTTCCCCAAAA")],vec![lk("b",'+',"b",'+')]), &[("b",true)], true);
        let pa = RepeatPlacement::Internal { host:"h".into(),strand:'+',tstart:4,tend:8 };
        let pb = RepeatPlacement::Internal { host:"b".into(),strand:'+',tstart:4,tend:8 };
        cross_prepare_walk(&a.gfa,&a.steps,true).unwrap(); cross_prepare_walk(&b.gfa,&b.steps,true).unwrap();
        let mut merged=build_inter_merge_internal_internal(&a.gfa,&pa,&b.gfa,&pb,"B","T","CCCC").unwrap();
        cross_remap_seed_links(&mut merged,&a,&b,&pa,&pb,"B","T").unwrap();
        assert!(merged.links.iter().any(|l| l.from_name=="B__b_B3" && l.to_name=="B__b_B5" && l.from_orient=='+' && l.to_orient=='+'));
        assert!(!merged.links.iter().any(|l| l.from_name=="B__b_B5" && l.to_name=="B__b_B5"));
        let aw=cross_replace_host_walk(&a,&pa,true,"B","T").unwrap();
        let bw=cross_replace_host_walk(&b,&pb,false,"B","T").unwrap();
        let (w,circle)=cross_splice_walks(&aw,true,&bw,true,"T").unwrap();
        let prepared=cross_prepare_walk(&merged,&w,circle).unwrap();
        assert_eq!(w.iter().filter(|s| s.node=="U").count(),2);
        assert_eq!(w.iter().filter(|s| s.node=="T").count(),2);
        assert_eq!(prepared.source_spell.len(),36);
        let transitions=w.windows(2).map(|p| (p[0].node.as_str(),p[1].node.as_str())).collect::<Vec<_>>();
        assert!(transitions.contains(&("T","B__b_B5")));
        assert!(transitions.contains(&("B__b_B3","T")));
        assert!(w.iter().filter(|s| s.node=="U").all(|s| !s.reverse));
        let stamp=repeat_test_stamp();
        let out=std::env::temp_dir().join(format!("r4-walk-{}-{stamp}.tsv",std::process::id()));
        assert_eq!(cross_write_draft_walk(&a,&b,&pa,&pb,&merged,"B","T",&out).unwrap(),prepared.source_spell);
        let evidence=fs::read_to_string(&out).unwrap();
        assert!(evidence.contains("non_target_source_sequences\tPASS"));
        fs::remove_file(out).unwrap();
        merged.segments.get_mut("h_A5").unwrap().sequence="TTTT".into();
        assert!(cross_check_preserved_parts(&merged,&a,&pa,true,"B").is_err());
    }

    #[test]
    fn cross_recorded_splice_rejects_unbound_linear_join_and_repeat_occurrence_choice() {
        use crate::commands::rebuild::PathStep;
        let s=|n:&str,r| PathStep {node:n.into(),reverse:r};
        let a=vec![s("a",false),s("T",false),s("z",false)];
        let b=vec![s("b",false),s("T",true),s("y",false)];
        assert!(cross_splice_walks(&a,false,&b,false,"T").is_err());
        let ambiguous=vec![s("T",false),s("x",false),s("T",true)];
        assert!(cross_splice_walks(&a,true,&ambiguous,true,"T").is_err());
        let (w,c)=cross_splice_walks(&a,false,&b,true,"T").unwrap();
        assert!(!c);
        assert_eq!(w,vec![s("a",false),s("T",false),s("b",true),s("y",true),s("T",false),s("z",false)]);
    }

    #[test]
    fn cross_derived_contract_exactly_encodes_the_existing_walk() {
        let stamp=repeat_test_stamp();
        let root=std::env::temp_dir().join(format!("r4-derived-contract-{}-{stamp}",std::process::id()));
        fs::create_dir(&root).unwrap();
        let seed=root.join("seed.gfa");let evidence=root.join("walk.tsv");
        let gfa=Gfa { headers:Vec::new(),segments:BTreeMap::from([
            ("L".into(),new_segment("L","ACGT".into(),"test")),
            ("R".into(),new_segment("R","CCGT".into(),"test")),
            ("V".into(),new_segment("V","GGTT".into(),"test"))]),
            order:vec!["R".into(),"V".into(),"L".into()],
            links:vec![lk("L",'+',"R",'+'),lk("R",'+',"V",'+'),lk("V",'+',"R",'+'),lk("R",'+',"L",'+')],other_lines:Vec::new() };
        gfa.write(&seed).unwrap();
        let input="section\tid\tkey\tvalue\ndraft\t.\tcircular\ttrue\ndraft\t.\toriented_nodes\tL+,R+,V+,R+\ndraft\t.\tsequence_length\t16\n";
        fs::write(&evidence,input).unwrap();
        let spell="ACGTCCGTGGTTCCGT";
        let encoded=cross_derived_resolve_details(&seed,&evidence,"merged",spell).unwrap();
        assert!(encoded.contains("selected_order\tR:A->R_cross_copy1\t"));
        assert!(encoded.contains("oriented_nodes\tL+,R+,V+,R_cross_copy1+\t"));
        assert!(encoded.contains("derived_from_adopted_cross_draft"));
        assert!(cross_derived_resolve_details(&seed,&evidence,"merged","TCGTCCGTGGTTCCGT").is_err());
        // The same graph can encode another pairing. Only the recorded walk is
        // accepted; changing its expected sequence cannot pass by reselection.
        fs::write(&evidence,input.replace("L+,R+,V+,R+","L+,R+,L+,R+")).unwrap();
        assert!(cross_derived_resolve_details(&seed,&evidence,"merged",spell).is_err());
        fs::remove_file(seed).unwrap();fs::remove_file(evidence).unwrap();fs::remove_dir(root).unwrap();
    }

