    fn lk(from: &str, fo: char, to_name: &str, to_orient: char) -> Link {
        Link {
            from_name: from.to_string(),
            from_orient: fo,
            to_name: to_name.to_string(),
            to_orient,
            overlap: "0M".to_string(),
            tags: Vec::new(),
        }
    }

    fn graph() -> Gfa {
        let names = ["C", "L1", "L2", "R7", "R"];
        let mut segments = BTreeMap::new();
        let mut order = Vec::new();
        for name in names {
            order.push(name.to_string());
            segments.insert(
                name.to_string(),
                Segment {
                    name: name.to_string(),
                    sequence: "A".to_string(),
                    tags: Vec::new(),
                },
            );
        }
        // Incident order for R mirrors B1S225 utg5.
        let links = vec![
            lk("L1", '+', "R", '-'),
            lk("C", '+', "R", '+'),
            lk("L2", '+', "R", '+'),
            lk("R", '+', "R7", '-'),
        ];
        Gfa {
            headers: Vec::new(),
            segments,
            order,
            links,
            other_lines: Vec::new(),
        }
    }

    fn neighbours(gfa: &Gfa, node: &str) -> BTreeSet<String> {
        let mut out = BTreeSet::new();
        for link in &gfa.links {
            if link.from_name == node {
                out.insert(link.to_name.clone());
            }
            if link.to_name == node {
                out.insert(link.from_name.clone());
            }
        }
        out
    }

    #[test]
    fn duplicate_then_strategy_a_matches_b1s225_partition() {
        let mut gfa = graph();
        let copied = duplicate_repeat_node(&mut gfa, "R", "R_copy1").unwrap();
        assert_eq!(copied, 4);
        assert_eq!(gfa.links.len(), 8);
        let (kept, removed) =
            resolve_duplicated_repeat(&mut gfa, "R", "R_copy1", "A").unwrap();
        assert_eq!((kept, removed), (4, 4));
        assert_eq!(gfa.links.len(), 4);
        assert_eq!(
            neighbours(&gfa, "R"),
            BTreeSet::from(["C".to_string(), "L1".to_string()])
        );
        assert_eq!(
            neighbours(&gfa, "R_copy1"),
            BTreeSet::from(["L2".to_string(), "R7".to_string()])
        );
    }

    #[test]
    fn strategy_b_swaps_the_plus_partner() {
        let mut gfa = graph();
        duplicate_repeat_node(&mut gfa, "R", "R_copy1").unwrap();
        resolve_duplicated_repeat(&mut gfa, "R", "R_copy1", "B").unwrap();
        assert_eq!(
            neighbours(&gfa, "R"),
            BTreeSet::from(["C".to_string(), "R7".to_string()])
        );
        assert_eq!(
            neighbours(&gfa, "R_copy1"),
            BTreeSet::from(["L1".to_string(), "L2".to_string()])
        );
    }

