    fn context_source_test_audit(component:&BundleComponent,audit:&Path,mode:GraphMeasurement) {
        fs::create_dir_all(audit).unwrap();write_graph_family_audit(component,audit);
        let dna=read_fasta(&component.component_fasta).unwrap()[0].sequence.clone();
        let path=audit.join("repeat_self_blast.tsv");
        let blast=fs::read_to_string(&path).unwrap().lines().map(|line|{
            let f=line.split('\t').collect::<Vec<_>>();
            let strand=|a:usize,b:usize|{let a=f[a].parse::<usize>().unwrap();let b=f[b].parse::<usize>().unwrap();
                let word=&dna[a.min(b)-1..a.max(b)];if a>b{reverse_complement(word)}else{word.into()}};
            format!("{line}\t{}\t{}\n",strand(6,7),strand(8,9))
        }).collect::<String>();fs::write(path,blast).unwrap();
        let graph=Gfa::read(&component.gfa).unwrap();let source=cross_read_source_walk(component).unwrap();
        let mut rows=adopt_pair_rows(audit).unwrap();
        let mut proofs=String::from("component_id\tgraph_node\tgraph_template_length_bp\tpolicy_length_basis\tproof_sha256\treads_sha256\tfour_path_templates_sha256\tsource_proof\n");
        for r in &mut rows {
            let node=graph_canonical_node(adopt_value(r,"canonical_repeat_id")).unwrap().to_string();
            let (b,_)=bind_graph_contexts_mode(component,&graph,&dna,&node,&source,audit,mode).unwrap();
            r.insert("graph_template_length_bp".into(),b.measurement_length().to_string());
            r.insert("graph_template_proof_sha256".into(),b.proof_sha256.clone());
            r.insert("graph_template_reads_sha256".into(),b.reads_sha256.clone());
            r.insert("graph_path_templates_sha256".into(),b.path_templates_sha256.clone());
            proofs.push_str(&format!("{}\t{node}\t{}\t{}\t{}\t{}\t{}\t{}\n",component.component_id,b.measurement_length(),b.measurement_basis(),b.proof_sha256,b.reads_sha256,b.path_templates_sha256,b.evidence));
        }
        let columns=rows[0].keys().cloned().collect::<Vec<_>>();
        fs::write(audit.join("canonical_repeat_pairs.tsv"),format!("{}\n{}",columns.join("\t"),rows.iter().map(|r|format!("{}\n",columns.iter().map(|c|r[c].as_str()).collect::<Vec<_>>().join("\t"))).collect::<String>())).unwrap();
        fs::write(audit.join("graph_template_bindings.tsv"),proofs).unwrap();
    }

    fn context_source_file_fixture() -> (Fixture,PathBuf,BundleComponent,PathBuf,AdoptRow) { context_source_file_fixture_mode(GraphMeasurement::MultiContext) }
    fn context_source_file_fixture_mode(mode:GraphMeasurement) -> (Fixture,PathBuf,BundleComponent,PathBuf,AdoptRow) {
        let mut f=Fixture::new(true,false);f.offset=0;
        let mut graph=Gfa::read(&f.component.gfa).unwrap();let mut state=9723u64;
        for (node,s) in &mut graph.segments {
            let n=if node=="edge_1"{80}else if node.starts_with("repeat_"){2100}else{6000};
            s.sequence=(0..n).map(|_|{state=state.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);[b'A',b'C',b'G',b'T'][((state>>62)&3)as usize]as char}).collect();
        }
        graph.write(&f.component.gfa).unwrap();let dna=cross_prepare_walk(&graph,&f.walk,true).unwrap().source_spell;
        fs::write(&f.component.component_fasta,format!(">authority\n{dna}\n")).unwrap();
        fs::copy(&f.component.component_fasta,f.component.rotated_reference.as_ref().unwrap()).unwrap();
        fs::copy(&f.component.component_fasta,f.component.validate_data_dir.as_ref().unwrap().parent().unwrap().join("01.inputs/rotated_reference.fasta")).unwrap();
        f.report(None,None,None);f.contract();
        let before=f.root.join("initial_contexts");context_source_test_audit(&f.component,&before,mode);
        let (component,mut row,_,_)=mock_downgrade_rebuild(&f);
        row.insert("component_id".into(),component.component_id.clone());row.insert("decision".into(),"adopt_downgrade".into());
        row.insert("node".into(),"edge_1".into());row.insert("copy_id".into(),"edge_1_copy1".into());
        let final_graph=Gfa::read(&component.gfa).unwrap();
        fs::write(Path::new(&row["extract_tsv"]),format!("subgraph\trow_type\tnode\tnode_length\tsource_length\tsource_kind\tsource_parts\n{}",final_graph.segments.iter().map(|(n,s)|format!("{}\tnode_copy\t{n}\t{}\t{}\tchecked_source\t{n}\n",component.component_id,s.sequence.len(),s.sequence.len())).collect::<String>())).unwrap();
        context_bind_parent_audit(&mut row,&before).unwrap();
        let bundle=f.root.join("context_parent.tsv");
        let mut unrelated=f.component.clone();unrelated.component_id="unrelated_component".into();unrelated.source_contract=None;
        adopt_write_bundle(&bundle,&AdoptComponents::from([(f.component.component_id.clone(),f.component.clone()),(unrelated.component_id.clone(),unrelated)])).unwrap();
        let after=f.root.join("candidate_contexts");fs::create_dir(&after).unwrap();
        let pending=adopt_write_audit_source_contract(&component,&row,&bundle,&BTreeSet::from([component.component_id.clone()]),&after).unwrap();
        context_source_test_audit(&pending,&after,mode);
        let contract=CurrentSourceContract::read(pending.source_contract.as_ref().unwrap(),&pending.component_id).unwrap();
        let record=adopt_fixed_record(&contract.file("audit_result",None).unwrap()).unwrap();
        (f,before,pending,after,record)
    }

    #[test]
    fn context_pool_scope_existing_audits_keep_proofs_and_reduce_full_hashes() {
        let(f,before,pending,after,_)=context_source_file_fixture();
        let counts=||CONTEXT_POOL_FULL_HASHES.with(|n|n.get());
        let reset=||{CONTEXT_POOL_FULL_HASHES.with(|n|n.set(0));CONTEXT_POOL_FULL_COMPARISONS.with(|n|n.set(0));};
        let root=AdoptComponents::from([(f.component.component_id.clone(),f.component.clone())]);
        reset();verify_graph_template_audit(&before,false,GraphMeasurement::MultiContext,true,Some(&root)).unwrap();
        let root_before=counts();let root_literal_before=CONTEXT_POOL_FULL_COMPARISONS.with(|n|n.get());
        reset();verify_graph_measurement_audit(&before,GraphMeasurement::MultiContext,Some(&root)).unwrap();
        let root_after=counts();let root_literal_after=CONTEXT_POOL_FULL_COMPARISONS.with(|n|n.get());
        let child=AdoptComponents::from([(pending.component_id.clone(),pending.clone())]);
        reset();verify_graph_template_audit(&after,false,GraphMeasurement::MultiContext,true,Some(&child)).unwrap();
        let child_before=counts();let child_literal_before=CONTEXT_POOL_FULL_COMPARISONS.with(|n|n.get());
        reset();verify_graph_measurement_audit(&after,GraphMeasurement::MultiContext,Some(&child)).unwrap();
        let child_after=counts();let child_literal_after=CONTEXT_POOL_FULL_COMPARISONS.with(|n|n.get());
        eprintln!("POOL_COUNTS root3 {root_before}->{root_after}; pending2_parent3 {child_before}->{child_after}");
        eprintln!("LITERAL_COUNTS root3 {root_literal_before}->{root_literal_after}; pending2_parent3 {child_literal_before}->{child_literal_after}");
        assert_eq!((root_before,root_after,child_before,child_after),(72,4,108,4));
        assert_eq!((root_literal_before,root_literal_after,child_literal_before,child_literal_after),(48,1,84,1));
        let collect=|| -> Result<Vec<String>,OrgraftError> {
            let graph=Gfa::read(&pending.gfa)?;
            let source=cross_read_source_walk(&pending)?;
            let authority=read_fasta(&pending.component_fasta)?[0].sequence.clone();
            graph_repeat_nodes(&graph).iter().map(|node|{
                let (binding,family)=bind_graph_contexts(&pending,&graph,&authority,node,&source,&after)?;
                Ok(format!("{binding:?}\n{family:?}"))
            }).collect()
        };
        let unshared=collect().unwrap();
        let shared=with_context_read_pool_scope(collect).unwrap();
        assert_eq!(unshared,shared,"all binding/proof/query/family fields must stay byte-identical");
        let blast=after.join("repeat_self_blast.tsv");let original=fs::read(&blast).unwrap();
        with_context_read_pool_scope(||{
            verify_graph_measurement_audit(&after,GraphMeasurement::MultiContext,Some(&child))?;
            fs::write(&blast,"changed HSP\n")?;
            assert!(verify_graph_measurement_audit(&after,GraphMeasurement::MultiContext,Some(&child)).is_err());
            Ok(())
        }).unwrap();
        fs::write(blast,original).unwrap();
    }

    #[test]
    #[cfg(unix)]
    fn context_pool_scope_still_maps_fresh_paf_and_never_reuses_counts() {
        use std::os::unix::fs::PermissionsExt;
        let(f,_,pending,after,_)=context_source_file_fixture();
        with_context_read_pool_scope(|| {
        let library=context_query_library(&pending,&after).unwrap();
        let current_node=library.current_to_origin.keys().next().unwrap();
        let original_node=&library.current_to_origin[current_node];
        let mut number=0;let mut selected=None;let mut sequences=Vec::new();
        for (node,paths) in &library.origin_queries {for p in paths {number+=1;sequences.push(p.sequence.clone());if node==original_node && selected.is_none(){selected=Some((number,p.sequence.len()));}}}
        let(index,len)=selected.unwrap();let mapper=f.root.join("fake-context-mapper.sh");
        let paf=format!("fresh_read\t{len}\t0\t{len}\t+\trepeat_path_{index:04}\t{len}\t0\t{len}\t{len}\t{len}\t60\ttp:A:P\tcg:Z:{len}=\n");
        fs::write(&mapper,format!("#!/bin/sh\nprintf '%s\\n' \"$@\" > '{}';\ncat <<'PAF'\n{paf}PAF\n",f.root.join("mapper_args").display())).unwrap();
        fs::set_permissions(&mapper,fs::Permissions::from_mode(0o755)).unwrap();
        let debug=f.root.join("context_mapping");let reads=pending.component_reads.as_ref().unwrap();
        let one=context_source_support_rows(&pending,&after,reads,&mapper,16,&debug,true).unwrap();
        assert_eq!(one.iter().map(|r|r.path_support.unwrap()).sum::<usize>(),1);
        assert_eq!(one.iter().filter(|r|r.path_support==Some(1)).next().unwrap().repeat_node,*current_node);
        assert!(one.iter().all(|r|r.support_method.contains("not_candidate_path_support")));
        let written=read_fasta(&debug.join("repeat_path_targets.fasta")).unwrap();
        assert_eq!(written.iter().map(|r|r.sequence.clone()).collect::<Vec<_>>(),sequences);
        assert_eq!(library.origin_queries.len(),3);assert_eq!(library.current_to_origin.len(),2);
        let args=fs::read_to_string(f.root.join("mapper_args")).unwrap();assert!(args.contains("\n-N\n50\n-t\n16\n"));assert_eq!(args.lines().last(),reads.to_str());
        // A second native mapping with different PAF output must change the
        // measured support. No pre-operation counts or saved support are read.
        fs::write(&mapper,"#!/bin/sh\nexit 0\n").unwrap();
        let zero=context_source_support_rows(&pending,&after,reads,&mapper,16,&f.root.join("context_mapping_again"),true).unwrap();
        assert_eq!(zero.iter().map(|r|r.path_support.unwrap()).sum::<usize>(),0);
            Ok(())
        }).unwrap();
    }

    #[test]
    fn read_pool_pipeline_literal_pair_once_and_typed_roles_only() {
        let f=Fixture::new(true,false);let a=f.root.join("pool_a");let b=f.root.join("pool_b");
        fs::write(&a,b"AAAA").unwrap();fs::write(&b,b"AAAA").unwrap();
        CONTEXT_POOL_FULL_COMPARISONS.with(|n|n.set(0));
        for _ in 0..3 { assert_eq!(cross_identical_read_pool(&a,&b).unwrap(),"identical_copy"); }
        assert_eq!(CONTEXT_POOL_FULL_COMPARISONS.with(|n|n.get()),3);
        CONTEXT_POOL_FULL_COMPARISONS.with(|n|n.set(0));CONTEXT_POOL_FULL_HASHES.with(|n|n.set(0));
        with_context_read_pool_scope(|| {
            for _ in 0..3 { assert_eq!(cross_identical_read_pool(&a,&b)?,"identical_copy"); }
            assert_eq!(cross_identical_read_pool(&b,&a)?,"identical_copy");
            assert_eq!(cross_identical_read_pool(&a,&a)?,"same_file");
            assert!(source_file_sha256(&b,Some(&a)).is_err(),"a typed field cannot borrow another pool, even equal bytes");
            let proof=f.root.join("proof.tsv");fs::write(&proof,b"AAAA")?;
            let first=source_file_sha256(&proof,None)?;fs::write(&proof,b"CCCC")?;
            assert_ne!(first,source_file_sha256(&proof,None)?,"non-pool evidence is never shared");
            Ok(())
        }).unwrap();
        assert_eq!(CONTEXT_POOL_FULL_COMPARISONS.with(|n|n.get()),1);
        assert_eq!(CONTEXT_POOL_FULL_HASHES.with(|n|n.get()),4,"two distinct files each require first and final full hashes");
        fs::write(&b,b"CCCC").unwrap();CONTEXT_POOL_FULL_COMPARISONS.with(|n|n.set(0));
        assert!(with_context_read_pool_scope(||cross_identical_read_pool(&a,&b)).is_err());
        assert_eq!(CONTEXT_POOL_FULL_COMPARISONS.with(|n|n.get()),1,"equal-size unequal copy fails the original literal comparison");
        assert!(CONTEXT_READ_POOL_EQUAL_PAIRS.with(|s|s.borrow().is_empty()));
    }

    #[test]
    #[cfg(unix)]
    fn read_pool_pipeline_cached_pair_rechecks_aliases_and_error_exit() {
        use std::os::unix::fs::symlink;
        let f=Fixture::new(true,false);let a=f.root.join("a");let b=f.root.join("b");let c=f.root.join("c");let alias=f.root.join("alias");
        for p in [&a,&b,&c] {fs::write(p,b"AAAA").unwrap();}symlink(&b,&alias).unwrap();
        assert!(with_context_read_pool_scope(|| {
            cross_identical_read_pool(&a,&b)?;cross_identical_read_pool(&a,&alias)?;
            fs::remove_file(&alias)?;symlink(&c,&alias)?;Ok(())
        }).is_err(),"every later alias of a cached pair is guarded");
        assert!(with_context_read_pool_scope(|| -> Result<(),OrgraftError> {
            use std::os::unix::fs::MetadataExt;
            cross_identical_read_pool(&a,&b)?;
            let before=fs::metadata(&b)?;let modified=before.modified()?;
            let ctime=(before.ctime(),before.ctime_nsec());
            let deadline=std::time::Instant::now()+std::time::Duration::from_secs(3);
            loop {
                // A restored-content test needs an observable metadata change;
                // consecutive writes may share one timestamp tick on Linux.
                std::thread::sleep(std::time::Duration::from_millis(20));
                fs::write(&b,b"CCCC")?;fs::write(&b,b"AAAA")?;
                fs::File::options().write(true).open(&b)?.set_times(fs::FileTimes::new().set_modified(modified))?;
                let after=fs::metadata(&b)?;
                assert_eq!(after.modified()?,modified);
                if (after.ctime(),after.ctime_nsec())!=ctime { break; }
                assert!(std::time::Instant::now()<deadline,"fixture requires an observable ctime change");
            }
            Err(adopt_error("body failed"))
        }).unwrap_err().to_string().contains("context read pool"));
        assert!(CONTEXT_READ_POOLS.with(|s|s.borrow().is_none()));
        assert!(CONTEXT_READ_POOL_EQUAL_PAIRS.with(|s|s.borrow().is_empty()));
    }

    #[test]
    fn context_pool_scope_checks_content_metadata_and_error_paths() {
        let f=Fixture::new(true,false);let pool=f.root.join("scope_reads.bin");
        fs::write(&pool,b"AAAA").unwrap();
        let changed=with_context_read_pool_scope(||{
            context_read_pool_sha256(&pool)?;
            let modified=fs::metadata(&pool)?.modified()?;
            fs::write(&pool,b"CCCC")?;
            fs::File::options().write(true).open(&pool)?.set_times(fs::FileTimes::new().set_modified(modified))?;
            Ok(())
        });
        assert!(changed.is_err(),"same-size content and restored mtime must fail");
        let metadata=with_context_read_pool_scope(||{
            context_read_pool_sha256(&pool)?;
            let modified=fs::metadata(&pool)?.modified()?+std::time::Duration::from_secs(1);
            fs::File::options().write(true).open(&pool)?.set_times(fs::FileTimes::new().set_modified(modified))?;
            assert!(context_read_pool_sha256(&pool).is_err());
            Ok(())
        });
        assert!(metadata.is_err(),"metadata-only mutation must fail at end too");
        CONTEXT_POOL_FULL_HASHES.with(|n|n.set(0));
        let error=with_context_read_pool_scope(|| -> Result<(),OrgraftError> {
            context_read_pool_sha256(&pool)?;Err(adopt_error("original body rejection"))
        });
        assert!(error.unwrap_err().to_string().contains("original body rejection"));
        assert_eq!(CONTEXT_POOL_FULL_HASHES.with(|n|n.get()),2,"Err still fully rehashes");
        let error=with_context_read_pool_scope(|| -> Result<(),OrgraftError> {
            context_read_pool_sha256(&pool)?;fs::write(&pool,b"GGGG")?;Err(adopt_error("original body rejection"))
        });
        assert!(error.unwrap_err().to_string().contains("context read pool"),"changed pool cannot hide behind original Err");
        let other=f.root.join("another_pool");fs::write(&other,b"TTTT").unwrap();
        CONTEXT_POOL_FULL_HASHES.with(|n|n.set(0));
        assert!(with_context_read_pool_scope(||{
            context_read_pool_sha256(&pool)?;context_read_pool_sha256(&other)?;
            fs::write(&pool,b"CCCC")?;Ok(())
        }).is_err());
        assert_eq!(CONTEXT_POOL_FULL_HASHES.with(|n|n.get()),4,"one failed pool must not skip the other's end hash");
        assert!(CONTEXT_READ_POOLS.with(|s|s.borrow().is_none()));
    }

