    #[test]
    fn context_pool_scope_is_nested_local_and_has_no_cross_call_cache() {
        let f=Fixture::new(true,false);let a=f.root.join("pool_a");let b=f.root.join("pool_b");
        fs::write(&a,b"AAAA").unwrap();fs::write(&b,b"CCCC").unwrap();
        CONTEXT_POOL_FULL_HASHES.with(|n|n.set(0));
        let pair=with_context_read_pool_scope(||{
            let first=context_read_pool_sha256(&a)?;
            with_context_read_pool_scope(||assert_eq_result(context_read_pool_sha256(&a)?,first.clone()))?;
            let second=context_read_pool_sha256(&b)?;
            Ok((first,second))
        }).unwrap();
        assert_ne!(pair.0,pair.1,"source is keyed by actual pool, not component ID");
        assert_eq!(CONTEXT_POOL_FULL_HASHES.with(|n|n.get()),4);
        with_context_read_pool_scope(||{context_read_pool_sha256(&a)?;Ok(())}).unwrap();
        assert_eq!(CONTEXT_POOL_FULL_HASHES.with(|n|n.get()),6);
        context_read_pool_sha256(&a).unwrap();context_read_pool_sha256(&a).unwrap();
        assert_eq!(CONTEXT_POOL_FULL_HASHES.with(|n|n.get()),8,"default/standalone path keeps full hashing");
        fn assert_eq_result(a:String,b:String)->Result<(),OrgraftError>{assert_eq!(a,b);Ok(())}
    }

    #[test]
    fn context_source_actual_parent_child_and_signed_consumer_are_bound() {
        let(f,before,pending,after,record)=context_source_file_fixture();
        let old=context_query_library(&f.component,&before).unwrap();let new=context_query_library(&pending,&after).unwrap();
        assert_eq!(old.origin_bindings.len(),3);assert_eq!(new.origin_bindings.len(),3);assert_eq!(new.current_to_origin.len(),2);
        assert_eq!(old.library_sha256,new.library_sha256);assert_ne!(old.chain_sha256,new.chain_sha256);
        verify_graph_measurement_audit(&after,GraphMeasurement::MultiContext,Some(&AdoptComponents::from([(pending.component_id.clone(),pending.clone())]))).unwrap();
        let result=f.root.join("context_verified_result.tsv");adopt_write_fixed_record(&result,&record).unwrap();
        let verification=f.root.join("context_verified_check.tsv");fs::write(&verification,"key\tvalue\ntarget_check\tdowngrade_two_copies_traced\nnon_target_check\tPASS\n").unwrap();
        let child=adopt_write_child_source_contract(&pending,&record,&result,&verification,&f.root.join("context_verified_source.tsv")).unwrap();
        verify_graph_measurement_audit(&after,GraphMeasurement::MultiContext,Some(&AdoptComponents::from([(child.component_id.clone(),child.clone())]))).unwrap();
        assert_eq!(new.library_sha256,context_query_library(&child,&after).unwrap().library_sha256);
        let mut changed=record.clone();changed.insert("context_resolved_gfa_sha256".into(),"0".repeat(64));
        let saved=fs::read(&result).unwrap();fs::write(&result,format!("key\tvalue\n{}",changed.iter().map(|(k,v)|format!("{k}\t{v}\n")).collect::<String>())).unwrap();
        assert!(context_query_library(&child,&after).is_err());fs::write(&result,saved).unwrap();
        let parent=before.join("repeat_self_blast.tsv");let saved=fs::read(&parent).unwrap();fs::write(&parent,"changed HSP\n").unwrap();
        assert!(context_query_library(&child,&after).is_err());fs::write(&parent,saved).unwrap();
        let mut wrong=child.clone();wrong.component_reads=Some(f.root.join("not-the-original-pool"));assert!(context_query_library(&wrong,&after).is_err());
    }

    #[test]
    fn context_source_parent_audit_rejects_resigned_other_tables_and_wrong_target() {
        let(f,before,pending,after,record)=context_source_file_fixture();
        let contract=CurrentSourceContract::read(pending.source_contract.as_ref().unwrap(),&pending.component_id).unwrap();
        let file=contract.file("audit_result",None).unwrap();let original=fs::read(&file).unwrap();
        let source_path=pending.source_contract.as_ref().unwrap();let saved_contract=fs::read(source_path).unwrap();
        let verification=contract.file("audit_verification",None).unwrap();let saved_verification=fs::read(&verification).unwrap();
        for mode in ["target","copy","audit","scope","origin_hash"] {
            let mut bad=record.clone();
            match mode {
                "target"=>{bad.insert("node".into(),"repeat_core_8887".into());},
                "copy"=>{bad.insert("copy_id".into(),"foreign_copy".into());},
                "audit"=>{bad.insert("context_parent_audit".into(),after.display().to_string());},
                "scope"=>{bad.insert("source_components".into(),"foreign_component".into());},
                _=>{bad.insert("context_parent:repeat_inputs.fasta_sha256".into(),"0".repeat(64));},
            }
            fs::write(&file,format!("key\tvalue\n{}",bad.iter().map(|(k,v)|format!("{k}\t{v}\n")).collect::<String>())).unwrap();
            let new_hash=sha256_hex(&fs::read(&file).unwrap());
            fs::write(&verification,String::from_utf8(saved_verification.clone()).unwrap().replace(&sha256_hex(&original),&new_hash)).unwrap();
            // Re-signing the outer source reference cannot repair wrong native
            // parent/target evidence; downstream replay must still reject it.
            let changed=String::from_utf8(saved_contract.clone()).unwrap().replace(&sha256_hex(&original),&new_hash).replace(&sha256_hex(&saved_verification),&sha256_hex(&fs::read(&verification).unwrap()));
            fs::write(source_path,changed).unwrap();
            assert!(context_query_library(&pending,&after).is_err(),"{mode}");
            fs::write(&file,&original).unwrap();fs::write(&verification,&saved_verification).unwrap();fs::write(source_path,&saved_contract).unwrap();
        }
        assert!(context_query_library(&pending,&after).is_ok());
        assert!(context_query_library(&f.component,&before).is_ok());
    }

