    #[test]
    fn context_source_real_two_reversed_sources_keep_queries_separate_from_paths() {
        for (id,node,target,authority_sha,stages) in [("B2S035:mito:pmat_v1","79","76","f8b930e204091e200c1a58b4ef2b7a67654df6b4634f375d3555342fbd12fb52",[(include_str!("../../tests/fixtures/b035_context_initial.gfa"),include_str!("../../tests/fixtures/b035_context_initial.walk"),168694,"0b884f7a00e5e3c380014212a0163c402fb2f31a6a45a905051cc1d0d97dc042"),(include_str!("../../tests/fixtures/b035_context_step_001.gfa"),include_str!("../../tests/fixtures/b035_context_step_001.walk"),168694,"c10b9445beb1a55d284246f6c020bca0a1f761c71b9338949ddf3100b1ffa847")]),("B2S058-5:mito:pmat_v1","83","81","31a0c7bda7b32b3d1be4ca05eae0fb33c86fa7245fa1d5e9fe98f080c2791dce",[(include_str!("../../tests/fixtures/b0585_context_initial.gfa"),include_str!("../../tests/fixtures/b0585_context_initial.walk"),97776,"b29f3d8488887be94b4361edfdbcae6b17c8e4373423f69822014b6382c8e68b"),(include_str!("../../tests/fixtures/b0585_context_step_001.gfa"),include_str!("../../tests/fixtures/b0585_context_step_001.walk"),97776,"c07287e5c211d73645794398457a8684c5b8581c06832a18e08706923ff20ebb")])] {
            let mut fixtures=Vec::new();let mut sources=Vec::new();let mut authorities=Vec::new();
            for (text,walk,offset,expected_sha) in stages {
                assert_eq!(sha256_hex(text.as_bytes()),expected_sha);
                let f=Fixture::new(false,false);fs::write(&f.component.gfa,text).unwrap();
                let graph=Gfa::read(&f.component.gfa).unwrap();
                let steps=walk.split(',').map(|s|PathStep{node:s[..s.len()-1].into(),reverse:s.ends_with('-')}).collect::<Vec<_>>();
                let spelling=reverse_complement(&cross_prepare_walk(&graph,&steps,true).unwrap().source_spell);
                let dna=format!("{}{}",&spelling[offset..],&spelling[..offset]);assert_eq!(sha256_hex(dna.as_bytes()),authority_sha);
                sources.push(CrossSourceWalk{origin:"verified_current_model",gfa:graph,steps,circular:true,details:f.root.join("test_only"),checked:f.component.gfa.clone(),closure_evidence:"real_signed_cache_pure_replay".into(),entry_gfa:f.component.gfa.clone(),restored_links:vec![],alignment_reverse_complemented:true,alignment_rotation_step:offset as isize});
                fixtures.push(f);authorities.push(dna);
            }
            assert_eq!(authorities[0],authorities[1]);let original=&sources[0];let current=&sources[1];let authority=&authorities[0];
            let contexts=|s:&CrossSourceWalk|repeat_node_path_contexts(&s.gfa,node,&context_source_occurrences(&s.gfa,s).unwrap(),0,0).unwrap();
            let before=contexts(original);let after=contexts(current);assert_eq!((before.len(),after.len()),(6,4),"{id}");
            let copy=format!("{target}_copy1");let(strategy,_)=downgrade_pairing(original,target,&copy,[0;4]).unwrap();
            let mut resolved=original.gfa.clone();duplicate_repeat_node(&mut resolved,target,&copy).unwrap();resolve_duplicated_repeat(&mut resolved,target,&copy,strategy).unwrap();
            let projection=project_context_source_library(original,current,authority,node,node,&before,&after,target,&copy,&resolved).unwrap();
            assert_eq!(projection.original_queries.len(),6);assert_eq!(projection.current_port_rows.len(),4);
            assert_eq!(projection.candidate_present.iter().filter(|x|**x).count(),4);assert_eq!(projection.removed_by_target.len(),2);
            let windows=|p:&[RepeatPathContext]|p.iter().map(|x|x.sequence[x.required_start..x.required_end].to_string()).collect::<BTreeSet<_>>();
            assert_eq!(windows(&before),windows(&after));
            assert_ne!(graph_context_digest(&before),graph_context_digest(&after));
            for i in projection.removed_by_target {assert!(!projection.candidate_present[i]);}
            let mut tampered=current.gfa.clone();tampered.links.remove(0);
            let raw_saved=resolved.clone();resolved.links[0].overlap="1M".into();
            assert!(project_context_source_library(original,current,authority,node,node,&before,&after,target,&copy,&resolved).is_err());
            assert!(project_context_source_library(original,current,authority,node,node,&before,&after,node,&copy,&raw_saved).is_err());
        }
    }

    // Pure source-geometry fixtures. They do not supply read counts or approve an operation.
    fn b091_actual_context_target_fixture(retained: bool) -> (Fixture, CrossSourceWalk, String) {
        let f = Fixture::new(false, false);
        let (g, c) = if retained { (
            include_str!("../../tests/fixtures/b091_context_current_retained.gfa"),
            include_str!("../../tests/fixtures/b091_context_current_retained.tsv")) } else { (
            include_str!("../../tests/fixtures/b091_context_current_initial.gfa"),
            include_str!("../../tests/fixtures/b091_context_current_initial.tsv")) };
        let values = c.lines().skip(1).map(|line| {
            let fields = line.split('\t').collect::<Vec<_>>();
            ((fields[0], fields[2]), fields[3])
        }).collect::<BTreeMap<_, _>>();
        assert_eq!(sha256_hex(g.as_bytes()), values[&("source", "gfa_sha256")]);
        assert_eq!(values[&("walk", "circular")], "true");
        assert_eq!(values[&("walk", "reverse_complemented")], "false");
        fs::write(&f.component.gfa, g).unwrap();
        let graph = Gfa::read(&f.component.gfa).unwrap();
        let steps = values[&("walk", "oriented_nodes")].split(',').map(|s|
            PathStep { node: s[..s.len()-1].into(), reverse: s.ends_with('-') }).collect::<Vec<_>>();
        let offset = values[&("walk", "authority_offset0")].parse::<usize>().unwrap();
        let spell = cross_prepare_walk(&graph, &steps, true).unwrap().source_spell;
        let authority = format!("{}{}", &spell[offset..], &spell[..offset]);
        assert_eq!(authority.len(), 190380);
        assert_eq!(sha256_hex(authority.as_bytes()), "871ba1858b1b5ad3499fe329242c10fff3dd1ff18a6df0848d4fb7728d5bceaf");
        let source = CrossSourceWalk { origin: if retained { "verified_isolated_candidate" } else { "verified_current_model" },
            gfa: graph, steps, circular: true, details: f.root.join("test_only_details"), checked: f.component.gfa.clone(),
            closure_evidence: "test_only_actual_source_geometry".into(), entry_gfa: f.component.gfa.clone(), restored_links: vec![],
            alignment_reverse_complemented: false, alignment_rotation_step: offset as isize };
        let occurrences = context_source_occurrences(&source.gfa, &source).unwrap();
        for (node, count) in occurrences { assert_eq!(count.to_string(), values[&("occurrence", node.as_str())]); }
        (f, source, authority)
    }

    fn context_target_resolve_geometry(source: &CrossSourceWalk, node: &str) -> (CrossSourceWalk, String) {
        let copy = format!("{node}_copy1");
        // Zero counts only ask the existing geometry function for its unique fixed-walk pairing.
        let (strategy, _) = downgrade_pairing(source, node, &copy, [0; 4]).unwrap();
        let mut gfa = source.gfa.clone();
        duplicate_repeat_node(&mut gfa, node, &copy).unwrap();
        resolve_duplicated_repeat(&mut gfa, node, &copy, strategy).unwrap();
        let steps = downgrade_derived_walk(source, &gfa, node, &copy).unwrap();
        let resolved = CrossSourceWalk { origin: source.origin, gfa, steps, circular: source.circular,
            details: source.details.clone(), checked: source.checked.clone(), closure_evidence: source.closure_evidence.clone(),
            entry_gfa: source.entry_gfa.clone(), restored_links: source.restored_links.clone(),
            alignment_reverse_complemented: source.alignment_reverse_complemented,
            alignment_rotation_step: source.alignment_rotation_step };
        context_source_occurrences(&resolved.gfa, &resolved).unwrap();
        (resolved, copy)
    }

    fn context_target_paths(source: &CrossSourceWalk, authority: &str) -> Vec<RepeatPathContext> {
        let occurrences = context_source_occurrences(&source.gfa, source).unwrap();
        let core = repeat_node_path_contexts(&source.gfa, "62", &occurrences, 0, 0).unwrap();
        let exact = context_exact_span(&source.gfa, authority, "62", source, &core).unwrap();
        assert_eq!((exact.length_bp, exact.left_extension_bp, exact.right_extension_bp), (156, 1, 0));
        assert_eq!(exact.template_copies.iter().map(|p| (p.start0, p.end0, p.strand)).collect::<BTreeSet<_>>(),
            BTreeSet::from([(83403, 83559, '-'), (162676, 162832, '+')]));
        repeat_node_path_contexts(&source.gfa, "62", &occurrences, 1, 0).unwrap()
    }

    #[test]
    fn context_target_actual_b091_current_probe_and_fixed_queries_have_distinct_roles() {
        let (_f, initial, authority) = b091_actual_context_target_fixture(false);
        let (_g, retained, same) = b091_actual_context_target_fixture(true);
        assert_eq!(authority, same);
        let original = context_target_paths(&initial, &authority);
        let current = context_target_paths(&retained, &authority);
        assert_eq!((original.len(), current.len()), (12, 6));
        assert_eq!(graph_context_digest(&original), "314634f0bc584fe08b92ce81eff0730d49bbaae9bd4c249f1748dfac4d77e9aa");
        assert_eq!(graph_context_digest(&current), "68ea8602524e0828ffb4f7f4dfa61e86cbb9d70a5592ed98a56439be5125f2bc");
        let (one, copy59) = context_target_resolve_geometry(&initial, "59");
        let p1 = context_target_paths(&one, &authority);
        let first = project_context_source_library(&initial, &one, &authority, "62", "62", &original, &p1, "59", &copy59, &one.gfa).unwrap();
        let (two, copy61) = context_target_resolve_geometry(&one, "61");
        let p2 = context_target_paths(&two, &authority);
        let second = project_context_source_library(&one, &two, &authority, "62", "62", &p1, &p2, "61", &copy61, &two.gfa).unwrap();
        assert_eq!(first.removed_by_target.len() + second.removed_by_target.len(), 6);
        assert_eq!(p2.len(), 6);
        let keys = |source: &CrossSourceWalk, paths: &[RepeatPathContext]| {
            let ports = context_source_ports(source, &authority, "62").unwrap();
            paths.iter().map(|p| (context_source_pair(p, &ports).unwrap(), p.sequence.clone(), p.required_start, p.required_end)).collect::<BTreeSet<_>>()
        };
        assert_eq!(keys(&two, &p2), keys(&retained, &current));
        let (split, copy62) = context_target_resolve_geometry(&retained, "62");
        let probe = downgrade_template_probe(&retained.gfa, &split.gfa, "62", &copy62).unwrap();
        let occurrences = context_source_occurrences(&retained.gfa, &retained).unwrap();
        let probe_paths = repeat_node_path_contexts(&probe, "62", &occurrences, 1, 0).unwrap();
        assert_eq!(graph_context_digest(&probe_paths), graph_context_digest(&current));
        assert_ne!(graph_context_digest(&probe_paths), graph_context_digest(&original));
        assert_eq!(context_removed_target_pairings(&retained, &split.gfa, "62", &copy62).unwrap().len(), 2);
    }

    #[test]
    fn context_target_actual_b091_rejects_changed_source_ports_and_unqualified_component() {
        let (_f, mut source, authority) = b091_actual_context_target_fixture(true);
        let paths = context_target_paths(&source, &authority);
        let (split, copy) = context_target_resolve_geometry(&source, "62");
        for mode in 0..3 {
            let mut wrong = split.gfa.clone();
            match mode {
                0 => { let s = &mut wrong.segments.get_mut(&copy).unwrap().sequence;
                    let base = if s.starts_with('A') { "C" } else { "A" }; s.replace_range(0..1, base); },
                1 => { let link = wrong.links.iter_mut().find(|l| l.from_name == copy).unwrap(); link.to_orient = if link.to_orient == '+' { '-' } else { '+' }; },
                _ => wrong.links.iter_mut().find(|l| l.from_name == copy || l.to_name == copy).unwrap().overlap = "1M".into(),
            }
            assert!(downgrade_template_probe(&source.gfa, &wrong, "62", &copy).is_err(), "changed source mode {mode}");
        }
        source.alignment_rotation_step += 1;
        assert!(context_source_ports(&source, &authority, "62").is_err());
        source.alignment_rotation_step -= 1;
        let occurrences = context_source_occurrences(&source.gfa, &source).unwrap();
        for node in ["41", "46"] {
            assert!(repeat_node_path_contexts(&source.gfa, node, &occurrences, 0, 0).is_err(), "unqualified component target {node}");
        }
        let (_g, initial, same) = b091_actual_context_target_fixture(false); assert_eq!(authority, same);
        let original = context_target_paths(&initial, &authority);
        let (one, copy59) = context_target_resolve_geometry(&initial, "59");
        let mut missing = context_target_paths(&one, &authority); missing.remove(0);
        assert!(project_context_source_library(&initial, &one, &authority, "62", "62", &original, &missing, "59", &copy59, &one.gfa).is_err());
        assert_ne!(graph_context_digest(&paths), graph_context_digest(&original));
    }

    fn maximal_graph_fixture() -> (Fixture, PathBuf) { graph_measurement_fixture(GraphMeasurement::MaximalExactSpan) }
    #[test]
    fn complete_family_alleles_preserves_exact_span_and_complete_family_policy() {
        let mode=GraphMeasurement::CompleteFamilyAlleles;
        let (f,audit)=graph_measurement_fixture(mode);
        let graph=Gfa::read(&f.component.gfa).unwrap();let source=cross_read_source_walk(&f.component).unwrap();
        let dna=read_fasta(&f.component.component_fasta).unwrap()[0].sequence.clone();
        let family=audit_complete_graph_family(&audit,&f.component,&graph,&dna,"R",&source).unwrap();
        let binding=bind_graph_measurement(&f.component,&graph,&dna,"R",&source,&family,mode,&audit).unwrap();
        assert_eq!((binding.exact.length_bp,binding.exact.left_extension_bp,binding.exact.right_extension_bp),(2200,100,0));
        assert_eq!((binding.measurement_length(),binding.measurement_extents()),(2201,(100,1)));
        assert_eq!(binding.alleles.as_ref().unwrap().copy_sha256.iter().collect::<BTreeSet<_>>().len(),2);
        assert!(binding.evidence.contains("observed_complete_alleles_only=true"));
        let components=AdoptComponents::from([(f.component.component_id.clone(),f.component.clone())]);
        verify_graph_measurement_audit(&audit,mode,Some(&components)).unwrap();
        for wrong in [GraphMeasurement::Default,GraphMeasurement::MaximalExactSpan] {
            assert!(verify_graph_measurement_audit(&audit,wrong,Some(&components)).is_err());
        }
        assert!(verify_graph_full_family_audit(&audit,true,Some(&components)).is_err());
        let row=&read_tsv_map(&audit.join("canonical_repeat_pairs.tsv")).unwrap()[0];
        let policy=adopt_bound_row_policy_with_measurement(row,&f.component,&audit,false,false,mode).unwrap();
        assert_eq!((policy.length_bp,policy.length_basis,policy.threshold),(Some(2201),Some(LengthBasis::CompleteFamily),Some(0.25)));
        let templates=repeat_node_path_templates_with_extents(&graph,"R",100,1).unwrap();
        assert_eq!(templates.len(),4);assert!(templates.iter().all(|(_,_,s,a,b)|s.len()==6201&&*a==1000&&*b==5201));
        let args=["--sample-bundle","bundle","--reads","reads","--graph-measurement","complete-family-alleles"].map(str::to_string);
        assert_eq!(Options::parse(&args).unwrap().graph_measurement,mode);
        for flag in ["--graph-full-family","--duplicate-template-full-span","--linear-chain-flanks"] {
            let mut bad=args.to_vec();bad.push(flag.into());assert!(Options::parse(&bad).is_err());
        }
    }

    #[test]
    fn complete_family_alleles_rejects_unobserved_combinations_and_incomplete_hsps() {
        let (f,audit)=graph_measurement_fixture(GraphMeasurement::CompleteFamilyAlleles);
        let graph=Gfa::read(&f.component.gfa).unwrap();let source=cross_read_source_walk(&f.component).unwrap();
        let dna=read_fasta(&f.component.component_fasta).unwrap()[0].sequence.clone();
        let family=audit_complete_graph_family(&audit,&f.component,&graph,&dna,"R",&source).unwrap();
        let exact=exact_graph_template(&graph,&dna,"R",&source).unwrap();
        let blast=fs::read_to_string(audit.join("repeat_self_blast.tsv")).unwrap();
        let check=|family:&GraphFamilyBinding,blast:&str|complete_family_allele_templates(&graph,&dna,"R",&source,family,&exact,&f.component.component_id,blast);
        for (column,value) in [(0,"wrong_component"),(2,"98.99"),(3,"2200"),(4,"0"),(5,"1"),(14,"wrong_actual_DNA")] {
            let bad=blast.lines().map(|line|{let mut v=line.split('\t').collect::<Vec<_>>();v[column]=value;v.join("\t")}).collect::<Vec<_>>().join("\n");
            assert!(check(&family,&bad).is_err(),"column {column}");
        }
        // More than one variant on a single side still yields only observed
        // complete alleles. No exact-copy substitution is permitted.
        let make_hsp=|candidate:&GraphFamilyBinding| {
            let c=&candidate.family_copies;
            let data=c.iter().map(|c|bound_circle_sequence(&dna,c.start0 as usize,c.end0 as usize,c.strand,false).unwrap()).collect::<Vec<_>>();
            let mismatches=data[0].bytes().zip(data[1].bytes()).filter(|(a,b)|a!=b).count();
            let coords=|c:&GraphCoreOccurrence|if c.strand=='+'{(c.start0+1,c.end0)}else{(c.end0,c.start0+1)};
            let (qs,qe)=coords(&c[0]);let (ss,se)=coords(&c[1]);let n=candidate.family_length_bp;let id=&f.component.component_id;
            (mismatches,format!("{id}\t{id}\t{}\t{n}\t{mismatches}\t0\t{qs}\t{qe}\t{ss}\t{se}\t0\t10000\t{}\t{}\t{}\t{}\n",100.0*(n-mismatches)as f64/n as f64,dna.len(),dna.len(),data[0],data[1]))
        };
        let mut one_sided=family.clone();one_sided.family_length_bp+=2;
        for c in &mut one_sided.family_copies {if c.strand=='+' {c.end0+=2;}else{c.start0-=2;}}
        let (mismatches,hsp)=make_hsp(&one_sided);assert!(mismatches>=2);
        let (measured,_,_)=check(&one_sided,&hsp).unwrap();assert_eq!(measured.length_bp,2203);
        // Both actual alleles now differ on both sides. Four port combinations
        // would contain two unseen haplotypes, even though the HSP remains >99%.
        let mut two_sided=family.clone();two_sided.family_length_bp+=1;
        for c in &mut two_sided.family_copies {if c.strand=='+' {c.start0-=1;}else{c.end0+=1;}}
        let c=&two_sided.family_copies;
        let data=c.iter().map(|c|bound_circle_sequence(&dna,c.start0 as usize,c.end0 as usize,c.strand,false).unwrap()).collect::<Vec<_>>();
        let mismatches=data[0].bytes().zip(data[1].bytes()).filter(|(a,b)|a!=b).count();assert_eq!(mismatches,2);
        let coords=|c:&GraphCoreOccurrence|if c.strand=='+'{(c.start0+1,c.end0)}else{(c.end0,c.start0+1)};
        let (qs,qe)=coords(&c[0]);let (ss,se)=coords(&c[1]);let n=two_sided.family_length_bp;let id=&f.component.component_id;
        let hsp=format!("{id}\t{id}\t{}\t{n}\t{mismatches}\t0\t{qs}\t{qe}\t{ss}\t{se}\t0\t10000\t{}\t{}\t{}\t{}\n",100.0*(n-mismatches)as f64/n as f64,dna.len(),dna.len(),data[0],data[1]);
        assert!(check(&two_sided,&hsp).unwrap_err().to_string().contains("unobserved complete-family allele"));
    }

    #[test]
    fn complete_family_alleles_consumer_rejects_source_ports_alleles_and_ids() {
        let mode=GraphMeasurement::CompleteFamilyAlleles;let (f,audit)=graph_measurement_fixture(mode);
        let (other,_)=graph_measurement_fixture(mode);
        let wrong=AdoptComponents::from([(other.component.component_id.clone(),other.component.clone())]);
        assert!(verify_graph_measurement_audit(&audit,mode,Some(&wrong)).is_err());
        for path in [&f.component.gfa,&f.component.component_fasta,f.component.component_reads.as_ref().unwrap(),f.component.source_contract.as_ref().unwrap(),f.component.rotated_reference.as_ref().unwrap(),&audit.join("repeat_inputs.fasta"),&audit.join("repeat_self_blast.tsv"),&audit.join("repeat_families.tsv")] {
            let bytes=fs::read(path).unwrap();fs::write(path,b"changed\n").unwrap();assert!(verify_graph_measurement_audit(&audit,mode,None).is_err(),"{}",path.display());fs::write(path,bytes).unwrap();
        }
        let proofpath=audit.join("graph_template_bindings.tsv");let saved=fs::read_to_string(&proofpath).unwrap();
        let canonpath=audit.join("canonical_repeat_pairs.tsv");let canonical=fs::read_to_string(&canonpath).unwrap();
        for key in ["family_id","measurement_copy_dna_sha256","measurement_copies","measurement_path_alleles","measurement_hsps","measurement_mode","bundle_fasta"] {
            let lines=saved.lines().collect::<Vec<_>>();let mut fields=lines[1].split('\t').map(str::to_string).collect::<Vec<_>>();
            let bad=fields[7].split(';').map(|p|if p.starts_with(&format!("{key}=")){format!("{key}=changed")}else{p.into()}).collect::<Vec<_>>().join(";");assert_ne!(bad,fields[7]);fields[7]=bad;fields[4]=sha256_hex(fields[7].as_bytes());
            let mut canon=canonical.lines().map(|line|line.split('\t').map(str::to_string).collect::<Vec<_>>()).collect::<Vec<_>>();
            let column=canon[0].iter().position(|s|s=="graph_template_proof_sha256").unwrap();canon[1][column]=fields[4].clone();
            fs::write(&canonpath,canon.iter().map(|row|format!("{}\n",row.join("\t"))).collect::<String>()).unwrap();
            fs::write(&proofpath,format!("{}\n{}\n",lines[0],fields.join("\t"))).unwrap();assert!(verify_graph_measurement_audit(&audit,mode,None).is_err(),"{key}");
        }
        fs::write(proofpath,saved).unwrap();fs::write(canonpath,canonical).unwrap();verify_graph_measurement_audit(&audit,mode,None).unwrap();
    }

