    #[test]
    fn maximal_graph_measurement_rejects_source_ports_hsp_and_wrong_bundle() {
        let (f,audit)=maximal_graph_fixture();let (other,_)=maximal_graph_fixture();
        let wrong=AdoptComponents::from([(other.component.component_id.clone(),other.component.clone())]);
        assert!(verify_graph_measurement_audit(&audit,GraphMeasurement::MaximalExactSpan,Some(&wrong)).is_err());
        for path in [&f.component.gfa,&f.component.component_fasta,f.component.component_reads.as_ref().unwrap(),f.component.source_contract.as_ref().unwrap(),f.component.rotated_reference.as_ref().unwrap(),&audit.join("repeat_inputs.fasta"),&audit.join("repeat_self_blast.tsv"),&audit.join("repeat_families.tsv")] {
            let bytes=fs::read(path).unwrap();fs::write(path,b"changed\n").unwrap();assert!(verify_graph_measurement_audit(&audit,GraphMeasurement::MaximalExactSpan,None).is_err(),"{}",path.display());fs::write(path,bytes).unwrap();
        }
        let graph=Gfa::read(&f.component.gfa).unwrap();let source=cross_read_source_walk(&f.component).unwrap();let dna=read_fasta(&f.component.component_fasta).unwrap()[0].sequence.clone();
        let family=audit_complete_graph_family(&audit,&f.component,&graph,&dna,"R",&source).unwrap();let mut bad=graph.clone();bad.links.pop();
        assert!(bind_graph_measurement(&f.component,&bad,&dna,"R",&source,&family,GraphMeasurement::MaximalExactSpan,&audit).is_err());
        let blast=fs::read_to_string(audit.join("repeat_self_blast.tsv")).unwrap();let bad=blast.lines().map(|line|{let mut v=line.split('\t').collect::<Vec<_>>();v[2]="98.99";v.join("\t")}).collect::<Vec<_>>().join("\n");
        fs::write(audit.join("repeat_self_blast.tsv"),bad).unwrap();assert!(verify_graph_measurement_audit(&audit,GraphMeasurement::MaximalExactSpan,None).is_err());
    }
    fn check_graph_measurement_downgrade(mode: GraphMeasurement) {
        let (f, audit) = graph_measurement_fixture(mode);
        let components = AdoptComponents::from([(f.component.component_id.clone(), f.component.clone())]);
        let mut rows = read_tsv_map(&audit.join("canonical_repeat_pairs.tsv")).unwrap();
        for (key, value) in [("p1_count", "100"), ("p2_count", "1"), ("p3_count", "1"), ("p4_count", "100"), ("denominator", "202")] {
            rows[0].insert(key.into(), value.into());
        }
        let decision = AdoptDecision {
            component_id: f.component.component_id.clone(),
            canonical_id: adopt_value(&rows[0], "canonical_repeat_id").into(),
            current_class: "graph_repeat_node".into(), decision: "adopt_downgrade".into(),
            note: "test complete-family post gate".into(), repeat_length_bp: 2201,
        };
        let call = |rows: &[AdoptRow]| adopt_downgrade_template_policy_gate(
            rows, &audit, &components, &[], &audit, &components, &decision, &AdoptRow::new(),
            false, false, mode,
        );
        // A valid maximal-span premeasurement still cannot replace the required
        // post-operation complete-family view with its original graph counts.
        assert!(call(&rows).unwrap_err().to_string().contains("downgrade needs one bound complete-family view"));
        rows[0].insert("policy_length_basis".into(), "graph_template_exact_span".into());
        assert!(call(&rows).is_err());
        rows[0].insert("policy_length_basis".into(), "complete_aligned_family".into());
        fs::write(f.component.source_contract.as_ref().unwrap(), "changed source").unwrap();
        assert!(call(&rows).is_err());
    }

