    #[test]
    fn graph_full_family_same_band_distinct_defaults_replays_real_native_source() {
        let (f, audit) = graph_family_fixture();
        let graph = Gfa::read(&f.component.gfa).unwrap();
        let source = cross_read_source_walk(&f.component).unwrap();
        let dna = read_fasta(&f.component.component_fasta).unwrap()[0]
            .sequence
            .clone();
        let exact = exact_graph_template(&graph, &dna, "R", &source).unwrap();
        assert_eq!(
            (
                exact.length_bp,
                exact.left_extension_bp,
                exact.right_extension_bp
            ),
            (2200, 100, 0)
        );
        assert!(!graph_family_needs_full_span(&graph, "R", 2200, 2100, true).unwrap());
        assert!(bind_graph_template_for_family(
            &f.component,
            &graph,
            &dna,
            "R",
            &source,
            Some(2200),
            false,
            false
        )
        .unwrap()
        .is_none());
        verify_graph_full_family_audit(
            &audit,
            true,
            Some(&AdoptComponents::from([(
                f.component.component_id.clone(),
                f.component.clone(),
            )])),
        )
        .unwrap();
        assert!(verify_graph_full_family_audit(&audit, false, None).is_err());
        let default_templates = repeat_node_path_templates(&graph, "R").unwrap();
        let full = repeat_node_path_templates_with_extents(&graph, "R", 100, 0).unwrap();
        assert_eq!(
            default_templates
                .iter()
                .map(|p| &p.2)
                .collect::<BTreeSet<_>>()
                .len(),
            4
        );
        assert!(full
            .iter()
            .all(|(_, _, dna, a, b)| dna.len() == 6200 && *a == 1000 && *b == 5200));
        assert_ne!(default_templates, full);
        assert!(bind_graph_template_for_family(
            &f.component,
            &graph,
            &dna,
            "R",
            &source,
            None,
            false,
            true
        )
        .is_err());
        let mut wrong = cross_read_source_walk(&f.component).unwrap();
        wrong.origin = "r3_resolve";
        assert!(bind_graph_template_for_family(
            &f.component,
            &graph,
            &dna,
            "R",
            &wrong,
            Some(2200),
            false,
            true
        )
        .unwrap()
        .is_none());
    }

