    fn check_graph_measurement_completion(mode: GraphMeasurement) {
        let (f, audit) = graph_measurement_fixture(mode);
        let (other, _) = graph_measurement_fixture(mode);
        let out = f.root.join("auto");
        fs::create_dir(&out).unwrap();
        fs::rename(&audit, out.join("01_assess")).unwrap();
        let audit = out.join("01_assess");
        let bundle = f.root.join("bundle.tsv");
        let other_bundle = other.root.join("bundle.tsv");
        for (path, component) in [(&bundle, &f.component), (&other_bundle, &other.component)] {
            adopt_write_bundle(
                path,
                &AdoptComponents::from([(component.component_id.clone(), component.clone())]),
            )
            .unwrap();
        }
        let names = [
            "canonical_repeat_pairs.tsv",
            "graph_template_bindings.tsv",
            "repeat_families.tsv",
            "repeat_inputs.fasta",
            "repeat_self_blast.tsv",
        ];
        let signature = |path: &Path| {
            format!(
                "{}:{}:{}",
                sha256_hex(&fs::read(path).unwrap()),
                fs::metadata(path).unwrap().len(),
                fs::canonicalize(path).unwrap().display()
            )
        };
        let save = |input: &Path, retained: &Path, stages: &[PathBuf], bundles: &[PathBuf]| {
            let mut inputs = BTreeMap::from([
                ("meta:graph_measurement".to_string(), mode.as_str().to_string()),
                ("path:bundle".into(), input.display().to_string()),
                ("file:bundle".into(), signature(input)),
            ]);
            let text = |values: &BTreeMap<String, String>| {
                format!(
                    "key\tvalue\n{}",
                    values
                        .iter()
                        .map(|(k, v)| format!("{k}\t{v}\n"))
                        .collect::<String>()
                )
            };
            let input_text = text(&inputs);
            fs::write(out.join("auto_inputs.tsv"), &input_text).unwrap();
            inputs.clear();
            let mut values = BTreeMap::from([
                ("schema".into(), "refine_auto_complete_v2".into()),
                (
                    "status".into(),
                    if stages.len() == 1 {
                        "no_change"
                    } else {
                        "confirmed"
                    }
                    .into(),
                ),
                ("input_digest".into(), sha256_hex(input_text.as_bytes())),
                ("retained_bundle".into(), retained.display().to_string()),
                ("file:retained_bundle".into(), signature(retained)),
            ]);
            for stage in stages {
                for name in names {
                    let path = stage.join(name);
                    values.insert(
                        format!("file:output:{}", path.strip_prefix(&out).unwrap().display()),
                        signature(&path),
                    );
                }
            }
            for path in bundles {
                values.insert(
                    format!("file:output:{}", path.strip_prefix(&out).unwrap().display()),
                    signature(path),
                );
            }
            fs::write(out.join("auto_complete.tsv"), text(&values)).unwrap();
        };
        let initial = vec![audit.clone()];
        save(&bundle, &bundle, &initial, &[]);
        repeat_auto::verify_graph_measurement(&out, mode).unwrap();
        assert!(repeat_auto::verify_graph_measurement(&out, GraphMeasurement::Default).is_err());
        // Both bundles are independently valid and have the same component/node keys.
        // Re-signing completion must not lend A's assessment to execution B.
        save(&other_bundle, &other_bundle, &initial, &[]);
        assert!(repeat_auto::verify_graph_measurement(&out, mode)
            .unwrap_err()
            .to_string()
            .contains("actual component inputs differ"));
        save(&bundle, &other_bundle, &initial, &[]);
        assert!(repeat_auto::verify_graph_measurement(&out, mode).is_err());
        save(&bundle, &bundle, &initial, &[]);
        let complete = fs::read_to_string(out.join("auto_complete.tsv")).unwrap();
        fs::write(
            out.join("auto_complete.tsv"),
            complete
                .lines()
                .filter(|l| !l.starts_with("file:output:01_assess/repeat_self_blast.tsv\t"))
                .map(|l| format!("{l}\n"))
                .collect::<String>(),
        )
        .unwrap();
        assert!(repeat_auto::verify_graph_measurement(&out, mode).is_err());
        // Exercise both native step layouts and the final retained bundle.
        let final_audit = out.join("03_post_assess/01_assess");
        fs::create_dir_all(&final_audit).unwrap();
        let final_bundle = out.join("02_adopt/post_adopt_bundle.tsv");
        fs::create_dir_all(final_bundle.parent().unwrap()).unwrap();
        for name in names {
            fs::copy(audit.join(name), final_audit.join(name)).unwrap();
        }
        for step in ["step_001", "compound"] {
            let step_audit = out
                .join("02_adopt/steps")
                .join(step)
                .join("post_assess/01_assess");
            fs::create_dir_all(&step_audit).unwrap();
            for name in names {
                fs::copy(audit.join(name), step_audit.join(name)).unwrap();
            }
            let step_bundle = out
                .join("02_adopt/steps")
                .join(step)
                .join("candidate_bundle.tsv");
            fs::copy(&bundle, &step_bundle).unwrap();
            fs::copy(&bundle, &final_bundle).unwrap();
            let stages = vec![audit.clone(), step_audit, final_audit.clone()];
            let bundles = vec![step_bundle.clone(), final_bundle.clone()];
            save(&bundle, &final_bundle, &stages, &bundles);
            repeat_auto::verify_graph_measurement(&out, mode).unwrap();
            for target in [&step_bundle, &final_bundle] {
                fs::copy(&other_bundle, target).unwrap();
                save(&bundle, &final_bundle, &stages, &bundles);
                assert!(repeat_auto::verify_graph_measurement(&out, mode)
                    .unwrap_err()
                    .to_string()
                    .contains("actual component inputs differ"));
                fs::copy(&bundle, target).unwrap();
            }
        }
        save(&bundle, &bundle, &initial, &[]);
        fs::write(audit.join("repeat_self_blast.tsv"), "changed HSP\n").unwrap();
        assert!(repeat_auto::verify_graph_measurement(&out, mode).is_err());
        fs::write(out.join("auto_inputs.tsv"), "key\tvalue\n").unwrap();
        assert!(repeat_auto::verify_graph_measurement(&out, mode).is_err());
        assert!(repeat_auto::verify_graph_measurement(&out, GraphMeasurement::Default).is_err());
        fs::write(
            out.join("auto_inputs.tsv"),
            "key\tvalue\nschema\trefine_auto_v2\n",
        )
        .unwrap();
        fs::write(
            out.join("auto_complete.tsv"),
            "key\tvalue\nschema\trefine_auto_complete_v2\n",
        )
        .unwrap();
        repeat_auto::verify_graph_measurement(&out, GraphMeasurement::Default).unwrap();
    }

