    #[test]
    fn graph_full_family_consumer_accepts_only_strict_pending_child_promotion() {
        let mut f = Fixture::new(true, false);
        f.offset = 0;
        let mut graph = Gfa::read(&f.component.gfa).unwrap();
        let mut state = 9723u64;
        for (node, segment) in &mut graph.segments {
            let len = if node == "edge_1" {
                80
            } else if node.starts_with("repeat_") {
                2100
            } else {
                6000
            };
            segment.sequence = (0..len)
                .map(|_| {
                    state = state
                        .wrapping_mul(6364136223846793005)
                        .wrapping_add(1442695040888963407);
                    [b'A', b'C', b'G', b'T'][((state >> 62) & 3) as usize] as char
                })
                .collect();
        }
        graph.write(&f.component.gfa).unwrap();
        let dna = cross_prepare_walk(&graph, &f.walk, true)
            .unwrap()
            .source_spell;
        fs::write(&f.component.component_fasta, format!(">authority\n{dna}\n")).unwrap();
        fs::copy(
            &f.component.component_fasta,
            f.component.rotated_reference.as_ref().unwrap(),
        )
        .unwrap();
        fs::copy(
            f.component.rotated_reference.as_ref().unwrap(),
            f.component
                .validate_data_dir
                .as_ref()
                .unwrap()
                .parent()
                .unwrap()
                .join("01.inputs/rotated_reference.fasta"),
        )
        .unwrap();
        f.report(None, None, None);
        f.contract();
        let (component, row, accepted, verified) = mock_downgrade_rebuild(&f);
        let bundle = f.root.join("source_bundle.tsv");
        adopt_write_bundle(
            &bundle,
            &AdoptComponents::from([(f.component.component_id.clone(), f.component.clone())]),
        )
        .unwrap();
        let audit = f.root.join("post_assess");
        fs::create_dir(&audit).unwrap();
        let pending = adopt_write_audit_source_contract(
            &component,
            &row,
            &bundle,
            &BTreeSet::from([f.component.component_id.clone()]),
            &audit,
        )
        .unwrap();
        write_graph_family_audit(&pending, &audit);
        let child = adopt_write_child_source_contract(
            &pending,
            &row,
            &accepted,
            &verified,
            &f.root.join("child.tsv"),
        )
        .unwrap();
        let components = |c: BundleComponent| AdoptComponents::from([(c.component_id.clone(), c)]);
        let proof = fs::read(audit.join("graph_template_bindings.tsv")).unwrap();
        verify_graph_full_family_audit(&audit, true, Some(&components(pending.clone()))).unwrap();
        verify_graph_full_family_audit(&audit, true, Some(&components(child.clone()))).unwrap();
        assert_eq!(
            proof,
            fs::read(audit.join("graph_template_bindings.tsv")).unwrap()
        );
        for mode in ["role", "verification", "actual_reads"] {
            let mut actual = child.clone();
            let path = if mode == "verification" {
                &verified
            } else {
                child.source_contract.as_ref().unwrap()
            };
            let saved = fs::read(path).unwrap();
            match mode {
                "role" => fs::write(
                    path,
                    String::from_utf8(saved.clone())
                        .unwrap()
                        .replace("verified_isolated_candidate", "verified_current_model"),
                )
                .unwrap(),
                "verification" => fs::write(path, "changed verification\n").unwrap(),
                "actual_reads" => actual.component_reads = None,
                _ => unreachable!(),
            }
            assert!(
                verify_graph_full_family_audit(&audit, true, Some(&components(actual))).is_err(),
                "{mode}"
            );
            fs::write(path, saved).unwrap();
        }
    }

    fn check_graph_measurement_promotion(mode: GraphMeasurement) {
        let mut f = Fixture::new(true, false);
        f.offset = 0;
        let mut graph = Gfa::read(&f.component.gfa).unwrap();
        let mut state = 9723u64;
        for (node, segment) in &mut graph.segments {
            let len = if node == "edge_1" {
                80
            } else if node.starts_with("repeat_") {
                2100
            } else {
                6000
            };
            segment.sequence = (0..len)
                .map(|_| {
                    state = state
                        .wrapping_mul(6364136223846793005)
                        .wrapping_add(1442695040888963407);
                    [b'A', b'C', b'G', b'T'][((state >> 62) & 3) as usize] as char
                })
                .collect();
        }
        graph.write(&f.component.gfa).unwrap();
        let dna = cross_prepare_walk(&graph, &f.walk, true)
            .unwrap()
            .source_spell;
        fs::write(&f.component.component_fasta, format!(">authority\n{dna}\n")).unwrap();
        fs::copy(
            &f.component.component_fasta,
            f.component.rotated_reference.as_ref().unwrap(),
        )
        .unwrap();
        fs::copy(
            f.component.rotated_reference.as_ref().unwrap(),
            f.component
                .validate_data_dir
                .as_ref()
                .unwrap()
                .parent()
                .unwrap()
                .join("01.inputs/rotated_reference.fasta"),
        )
        .unwrap();
        f.report(None, None, None);
        f.contract();
        let (component, row, accepted, verified) = mock_downgrade_rebuild(&f);
        let bundle = f.root.join("source_bundle.tsv");
        adopt_write_bundle(
            &bundle,
            &AdoptComponents::from([(f.component.component_id.clone(), f.component.clone())]),
        )
        .unwrap();
        let audit = f.root.join("post_assess");
        fs::create_dir(&audit).unwrap();
        let pending = adopt_write_audit_source_contract(
            &component,
            &row,
            &bundle,
            &BTreeSet::from([f.component.component_id.clone()]),
            &audit,
        )
        .unwrap();
        write_graph_family_audit(&pending, &audit);
        let graph = Gfa::read(&pending.gfa).unwrap();
        let dna = read_fasta(&pending.component_fasta).unwrap()[0].sequence.clone();
        let source = cross_read_source_walk(&pending).unwrap();
        let blast_path = audit.join("repeat_self_blast.tsv");
        let blast = fs::read_to_string(&blast_path).unwrap().lines().map(|line| {
            let fields = line.split('\t').collect::<Vec<_>>();
            let sequence = |a: usize, b: usize| {
                let start = fields[a].parse::<usize>().unwrap();
                let end = fields[b].parse::<usize>().unwrap();
                let part = &dna[start.min(end)-1..start.max(end)];
                if start > end { reverse_complement(part) } else { part.to_string() }
            };
            format!("{line}\t{}\t{}\n", sequence(6,7), sequence(8,9))
        }).collect::<String>();
        fs::write(blast_path, blast).unwrap();
        let mut rows = read_tsv_map(&audit.join("canonical_repeat_pairs.tsv")).unwrap();
        let mut proofs = String::from("component_id\tgraph_node\tgraph_template_length_bp\tpolicy_length_basis\tproof_sha256\treads_sha256\tfour_path_templates_sha256\tsource_proof\n");
        for row in &mut rows {
            let node = graph_canonical_node(adopt_value(row, "canonical_repeat_id")).unwrap().to_string();
            let family = audit_complete_graph_family(&audit, &pending, &graph, &dna, &node, &source).unwrap();
            let binding = bind_graph_measurement(&pending, &graph, &dna, &node, &source, &family, mode, &audit).unwrap();
            row.insert("graph_template_length_bp".into(),binding.measurement_length().to_string());
            row.insert("graph_template_proof_sha256".into(), binding.proof_sha256.clone());
            row.insert("graph_template_reads_sha256".into(), binding.reads_sha256.clone());
            row.insert("graph_path_templates_sha256".into(), binding.path_templates_sha256.clone());
            proofs.push_str(&format!("{}\t{node}\t{}\t{}\t{}\t{}\t{}\t{}\n", pending.component_id, binding.measurement_length(), binding.measurement_basis(), binding.proof_sha256, binding.reads_sha256, binding.path_templates_sha256, binding.evidence));
        }
        let columns = rows[0].keys().cloned().collect::<Vec<_>>();
        fs::write(audit.join("canonical_repeat_pairs.tsv"), format!("{}\n{}", columns.join("\t"), rows.iter().map(|row| format!("{}\n", columns.iter().map(|c| row[c].as_str()).collect::<Vec<_>>().join("\t"))).collect::<String>())).unwrap();
        fs::write(audit.join("graph_template_bindings.tsv"), proofs).unwrap();
        let child = adopt_write_child_source_contract(
            &pending,
            &row,
            &accepted,
            &verified,
            &f.root.join("child.tsv"),
        )
        .unwrap();
        let components = |c: BundleComponent| AdoptComponents::from([(c.component_id.clone(), c)]);
        let proof = fs::read(audit.join("graph_template_bindings.tsv")).unwrap();
        verify_graph_measurement_audit(&audit, mode, Some(&components(pending.clone()))).unwrap();
        verify_graph_measurement_audit(&audit, mode, Some(&components(child.clone()))).unwrap();
        assert_eq!(
            proof,
            fs::read(audit.join("graph_template_bindings.tsv")).unwrap()
        );
        for change in ["role", "verification", "actual_reads"] {
            let mut actual = child.clone();
            let path = if change == "verification" {
                &verified
            } else {
                child.source_contract.as_ref().unwrap()
            };
            let saved = fs::read(path).unwrap();
            match change {
                "role" => fs::write(
                    path,
                    String::from_utf8(saved.clone())
                        .unwrap()
                        .replace("verified_isolated_candidate", "verified_current_model"),
                )
                .unwrap(),
                "verification" => fs::write(path, "changed verification\n").unwrap(),
                "actual_reads" => actual.component_reads = None,
                _ => unreachable!(),
            }
            assert!(
                verify_graph_measurement_audit(&audit, mode, Some(&components(actual))).is_err(),
                "{change}"
            );
            fs::write(path, saved).unwrap();
        }
    }

    fn chain_fixture() -> (Fixture, PathBuf) {
        let f = Fixture::new(false, false);
        let mut graph = Gfa::read(&f.component.gfa).unwrap();
        for (id, segment) in &mut graph.segments {
            if id != "cross_13805" { segment.sequence = segment.sequence.repeat(700); }
        }
        graph.segments.get_mut("c1__edge_1_p1").unwrap().sequence = "G".into();
        graph.write(&f.component.gfa).unwrap();
        let dna = cross_prepare_walk(&graph, &f.walk, true).unwrap().source_spell;
        fs::write(&f.component.component_fasta, format!(">authority\n{dna}\n")).unwrap();
        fs::copy(&f.component.component_fasta, f.component.rotated_reference.as_ref().unwrap()).unwrap();
        let round=f.component.validate_data_dir.as_ref().unwrap().parent().unwrap();
        fs::copy(f.component.rotated_reference.as_ref().unwrap(), round.join("01.inputs/rotated_reference.fasta")).unwrap();
        f.report(None,None,None); f.contract();
        let audit = f.root.join("audit"); fs::create_dir(&audit).unwrap();
        fs::write(audit.join("canonical_repeat_pairs.tsv"),format!("component_id\tcanonical_repeat_id\tcurrent_class\n{}\tgr_000_cross_13805\tgraph_repeat_node\n",f.component.component_id)).unwrap();
        write_linear_chain_proof(&audit, &[f.component.clone()]).unwrap();
        (f,audit)
    }

