            let q=format!("{shared}A{exact}GTTAC");
            let aligned=format!("{shared}C{exact}-TTAC");
            let sequences=[("W",dna(3,2300)),("cross_13805",shared),("A",format!("A{exact}GTTAC")),
                ("U",dna(43,2300)),("B",format!("C{exact}TTAC")),("V",dna(79,2300))];
            before.walk=["W","cross_13805","A","U","cross_13805","B","V"].into_iter()
                .map(|node|PathStep{node:node.into(),reverse:false}).collect();
