    #[test]
    fn initial_identity_exact_core_rejects_changed_context_method_readpool_and_evidence() {
        for mode in 0..8 {
            let mut f=IdentityFixture::exact_core();
            match mode {
                0=>f.options.intra_measurement=IntraMeasurement::FullCopy,
                1=>{fs::write(f.before.component.component_reads.as_ref().unwrap(),"@different\nTGCA\n+\nIIII\n").unwrap();},
                2=>{let p=f.options.out_dir.join("03_post_assess/01_assess/repeat_self_blast.tsv");fs::write(p,"changed HSP\n").unwrap();},
                3=>{let p=f.options.out_dir.join("03_post_assess/01_assess/intra_units.tsv");let t=fs::read_to_string(&p).unwrap().replace("\t200\t","\t199\t");fs::write(p,t).unwrap();},
                4=>{let p=f.options.out_dir.join("02_adopt/steps/step_001/post_assess/01_assess/intra_units.tsv");let t=fs::read_to_string(&p).unwrap().replace("source_bound_unique_exact_shared_core","full_copy_endpoints");fs::write(p,t).unwrap();},
                5=>{let p=f.options.out_dir.join("03_post_assess/01_assess/repeat_inputs.fasta");fs::write(p,">subgraph_cross\nACGT\n").unwrap();},
                6=>{f.confirmations[0].insert("candidate_bundle".into(),f.options.sample_bundle.display().to_string());},
                _=>{
                    // A different but internally valid native pool cannot be
                    // substituted just because its aggregate unit is unchanged.
                    let child=&mut f._after;
                    child.component.component_reads=Some(child.root.join("reads.fastq"));
                    fs::write(child.component.component_reads.as_ref().unwrap(),"@different\nTGCA\n+\nIIII\n").unwrap();
                    child.component.rotated_reference=Some(child.root.join("reference.fasta"));
                    fs::copy(&child.component.component_fasta,child.component.rotated_reference.as_ref().unwrap()).unwrap();
                    child.component.validate_data_dir=Some(child.root.join("validate/round_2/03.validate"));
                    let round=child.component.validate_data_dir.as_ref().unwrap().parent().unwrap();
                    fs::copy(child.component.component_reads.as_ref().unwrap(),round.join("01.inputs/subgraph_reads.fastq.gz")).unwrap();
                    fs::copy(child.component.rotated_reference.as_ref().unwrap(),round.join("01.inputs/rotated_reference.fasta")).unwrap();
                    for file in ["01.data/sv_read_index.tsv","01.data/sv_read_evidence.tsv","03.reports/sv_subgroup_stats.tsv"] {
                        let p=child.component.validate_data_dir.as_ref().unwrap().join(file);fs::create_dir_all(p.parent().unwrap()).unwrap();fs::write(p,"fixture_native_sv_evidence\n").unwrap();
                    }
                    child.report(None,None,None); child.contract();
                    cross_read_source_walk(&child.component).unwrap();
                    adopt_write_bundle(Path::new(&f.confirmations[0]["candidate_bundle"]),
                        &AdoptComponents::from([(child.component.component_id.clone(),child.component.clone())])).unwrap();
                },
            }
            assert!(repeat_auto::replay_resolved_identity_review(&f.options,&f.row,&f.confirmations).is_err(),"mode={mode}");
        }
    }

    #[test]
    fn initial_identity_review_replays_confirmed_complete_copies_without_clearing_other_review() {
        let f = IdentityFixture::new();
        let proof =
            repeat_auto::replay_resolved_identity_review(&f.options, &f.row, &f.confirmations).unwrap();
        assert_eq!(proof["status"], "resolved_by_confirmed_downgrade");
        assert_eq!(f.row["auto_status"], "review_required");
        let mut unrelated = f.row.clone();
        unrelated.insert(
            "action_reason".into(),
            "independent missing read evidence".into(),
        );
        assert!(repeat_auto::replay_initial_reviews(
            &f.options,
            &[f.row.clone(), unrelated],
            &f.confirmations
        )
        .unwrap());
        let rows = read_tsv_map(&f.options.out_dir.join("auto_review_replay.tsv")).unwrap();
        assert_eq!(
            rows.iter()
                .filter(|r| adopt_value(r, "status") == "review_required")
                .count(),
            1
        );
        assert_eq!(
            rows.iter()
                .filter(|r| adopt_value(r, "status") == "resolved_by_confirmed_downgrade")
                .count(),
            1
        );
    }
    #[test]
    fn initial_identity_review_rejects_changed_counts_copy_frame_hash_and_unconfirmed_target() {
        for mode in 0..8 {
            let mut f = IdentityFixture::new();
            match mode {
                0 => {
                    f.confirmations[0].insert("overall_status".into(), "confirm_failed".into());
                }
                1 => {
                    f.confirmations[0].insert(
                        "requested_canonical_repeat_id".into(),
                        "gr_000_missing".into(),
                    );
                }
                2 => {
                    let p = f
                        .options
                        .out_dir
                        .join("03_post_assess/01_assess/intra_units.tsv");
                    let text = fs::read_to_string(&p)
                        .unwrap()
                        .replace("\t6\t0\t0\t4\t10\t", "\t5\t1\t0\t4\t10\t");
                    fs::write(p, text).unwrap();
                }
                3 => {
                    f.confirmations[0].insert("family_copy_projection_sha256".into(), "changed".into());
                }
                4 | 5 => {
                    let p = PathBuf::from(&f.confirmations[0]["family_copy_projection"]);
                    let mut lines = read_tsv_map(&p).unwrap();
                    lines[0].insert(
                        if mode == 4 { "start0" } else { "strand" }.into(),
                        if mode == 4 { "999" } else { "-" }.into(),
                    );
                    let columns = lines[0].keys().cloned().collect::<Vec<_>>();
                    let text = format!(
                        "{}\n{}",
                        columns.join("\t"),
                        lines
                            .iter()
                            .map(|r| format!(
                                "{}\n",
                                columns
                                    .iter()
                                    .map(|k| r[k].as_str())
                                    .collect::<Vec<_>>()
                                    .join("\t")
                            ))
                            .collect::<String>()
                    );
                    fs::write(&p, &text).unwrap();
                    f.confirmations[0].insert(
                        "family_copy_projection_sha256".into(),
                        sha256_hex(text.as_bytes()),
                    );
                }
                6 => {
                    let p = f
                        .options
                        .out_dir
                        .join("03_post_assess/01_assess/repeat_families.tsv");
                    let text = fs::read_to_string(&p)
                        .unwrap()
                        .replace("F\t", "different_physical_family\t");
                    fs::write(p, text).unwrap();
                }
                _ => {
                    fs::write(&f.before.component.component_fasta, ">changed\nACGT\n").unwrap();
                }
            }
            assert!(
                repeat_auto::replay_resolved_identity_review(&f.options, &f.row, &f.confirmations)
                    .is_err(),
                "mode={mode}"
            );
        }
    }

