    fn isolated_candidate_contract(f: &Fixture) {
        let path = f.component.source_contract.as_ref().unwrap();
        let text = fs::read_to_string(path).unwrap()
            .replace("\tverified_current_model\n", "\tverified_isolated_candidate\n")
            .replace("\taccepted_result", "\tcandidate_result")
            .replace("\taccepted_verification", "\tcandidate_verification");
        fs::write(path, text).unwrap();
    }

    #[test]
    fn isolated_candidate_preserves_origin_exact_frame_and_occurrences() {
        for reverse in [false, true] {
            let f = Fixture::new(true, reverse); isolated_candidate_contract(&f);
            let source = cross_read_source_walk(&f.component).unwrap();
            assert_eq!(source.origin, "verified_isolated_candidate");
            assert_eq!(source.steps, f.walk);
            assert_eq!(source.alignment_reverse_complemented, reverse);
            assert_eq!(source.alignment_rotation_step, f.offset as isize);
            assert!(source.restored_links.is_empty());
            assert!(source.closure_evidence.starts_with("content_bound_candidate_fixed_walk:"));
            let authority = read_fasta(&f.component.component_fasta).unwrap()[0].sequence.clone();
            let mut current = cross_read_source_walk(&f.component).unwrap(); current.origin = "verified_current_model";
            let candidate_copies = fixed_graph_core_occurrences(&source, &authority, "edge_1");
            let current_copies = fixed_graph_core_occurrences(&current, &authority, "edge_1");
            assert_eq!(format!("{candidate_copies:?}"), format!("{current_copies:?}"));
        }
    }

    #[test]
    fn isolated_candidate_keeps_all_evidence_hash_and_frame_guards() {
        for key in ["candidate_result_sha256", "candidate_verification_sha256", "gfa_sha256", "component_fasta_sha256",
            "component_reads_sha256", "rotated_reference_sha256", "validation_report_sha256", "validation_fasta_sha256"] {
            let f = Fixture::new(false, false); isolated_candidate_contract(&f);
            f.set("source", key, &"0".repeat(64));
            assert!(f.error().contains("content changed"), "{key}");
        }
        let f = Fixture::new(false, false); isolated_candidate_contract(&f);
        f.set("walk", "authority_offset0", "1"); assert!(f.error().contains("do not replay"));
        let f = Fixture::new(false, false); isolated_candidate_contract(&f);
        let mut graph = Gfa::read(&f.component.gfa).unwrap();
        let mut bad = new_link("cross_13805", '+', "c2__edge_2_p1", '-'); bad.overlap = "999M".into(); graph.links.push(bad);
        graph.write(&f.component.gfa).unwrap(); f.refresh("gfa", &f.component.gfa);
        assert!(f.error().contains("overlap does not match"));
    }

