    #[test]
    fn exact_shared_core_keeps_distinct_complete_family_boundary_bases() {
        let (mut a,mut b,child)=fixture();
        // The complete homologous copies differ at the first base. Surgery
        // shares only their exact core; both original boundary bases remain.
        a.target_copy=copy(&a.path,1,6,'+');
        b.target_copy=copy(&b.path,2,7,'+');
        let lineage=cross_derive_copy_lineage(&a,&b,&child,"R").unwrap();
        let projected=cross_project_complete_family(&lineage,&[a.target_copy.clone(),b.target_copy.clone()]).unwrap();
        assert_eq!((projected[0].target.start0,projected[0].target.end0),(1,6));
        assert_eq!((projected[1].target.start0,projected[1].target.end0),(9,14));
        assert_eq!(&child.authority_sequence[1..6],"TATGC");
        assert_eq!(&child.authority_sequence[9..14],"AATGC");
    }
