    #[test]
    fn compound_source_completion_binds_original_and_normalized_artifacts() {
        let f = Fixture::new(false);
        let (bundle, _) = publish(&f);
        let options = Options::parse(&[
            "--sample-bundle".into(),
            f.bundle.display().to_string(),
            "--reads".into(),
            f.component
                .component_reads
                .as_ref()
                .unwrap()
                .display()
                .to_string(),
            "--out-dir".into(),
            f.root.display().to_string(),
            "--graph-measurement".into(),
            "multi-context".into(),
        ])
        .unwrap();
        let sig = repeat_auto::compound_test_snapshot(&options, &bundle).unwrap();
        for suffix in [
            "00_source/inputs.tsv",
            "00_source/normalization.tsv",
            "00_source/subgraph_001/proof.tsv",
            "00_source/subgraph_001/source.tsv",
            "00_source/subgraph_001/trace.tsv",
            "00_source/subgraph_001/normalized.gfa",
        ] {
            assert!(
                sig.contains_key(&format!("file:output:01_assess/{suffix}")),
                "missing {suffix}"
            );
        }
        assert!(sig.contains_key("file:retained:subgraph_001:compound:source_bundle"));
        assert!(sig.contains_key("file:retained:subgraph_001:compound:parent_component_reads"));
        let path = f.root.join("01_assess/00_source/normalization.tsv");
        let old = fs::read(&path).unwrap();
        fs::write(&path, [old.as_slice(), b"extra\tchanged\n"].concat()).unwrap();
        let changed = repeat_auto::compound_test_snapshot(&options, &bundle).unwrap();
        assert_ne!(sig, changed);
        fs::write(path, old).unwrap();
        assert_eq!(
            sig,
            repeat_auto::compound_test_snapshot(&options, &bundle).unwrap()
        );
    }
    #[test]
    fn compound_source_preserves_unaffected_P_and_rejects_inconsistent_P() {
        let f = Fixture::new(false);
        let (mut source, dna, families, blast) = f.data();
        let row = vec![
            "P".into(),
            "outside".into(),
            "B+,C+".into(),
            "0M".into(),
            "RC:i:17".into(),
        ];
        source.gfa.other_lines.push(row.clone());
        let p = compound_source::build(&source, &dna, &families, &families[0], &blast, "macro")
            .unwrap();
        assert!(p.graph.other_lines.contains(&row));
        assert_eq!(
            p.trace
                .lines()
                .filter(|x| x.starts_with("physical_edge\t"))
                .count(),
            source.gfa.links.len()
        );
        source.gfa.other_lines.last_mut().unwrap()[3] = "1M".into();
        assert!(
            compound_source::build(&source, &dna, &families, &families[0], &blast, "macro")
                .is_err()
        );
        source.gfa.other_lines.last_mut().unwrap()[2] = "absent+".into();
        source.gfa.other_lines.last_mut().unwrap()[3] = "*".into();
        assert!(
            compound_source::build(&source, &dna, &families, &families[0], &blast, "macro")
                .is_err()
        );
    }

    fn write_context_audit(f: &Fixture, c: &BundleComponent, audit: &Path) {
        let (_, dna, families, _) = f.data();
        let id = &c.component_id;
        fs::write(audit.join("repeat_inputs.fasta"), format!(">{id}\n{dna}\n")).unwrap();
        fs::write(audit.join("repeat_families.tsv"),format!("repeat_family_id\tcomponent_id\tstart_0based\tend_0based_exclusive\tstrand\tcopy_length_bp\treference_length_bp\tmin_edge_identity\tevidence_hsp_count\tfamily_scope\tn_copies\n{}",families.iter().flat_map(|family|family.copies.iter().map(move |c|format!("{}\t{id}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\tintra_component\t{}\n",family.id,c.start0,c.end0,c.strand,c.end0-c.start0,family.reference_length,family.min_identity,family.hsp_count,family.copies.len()))).collect::<String>())).unwrap();
        let graph=Gfa::read(&c.gfa).unwrap();let source=cross_read_source_walk(c).unwrap();
        let mut rows=Vec::new();
        let mut proofs=String::from("component_id\tgraph_node\tgraph_template_length_bp\tpolicy_length_basis\tproof_sha256\treads_sha256\tfour_path_templates_sha256\tsource_proof\n");
        for node in graph_repeat_nodes(&graph) {
            let (binding,family)=bind_graph_contexts(c,&graph,&dna,&node,&source,audit).unwrap();
            rows.push(AdoptRow::from([
                ("component_id".into(),id.clone()),("canonical_repeat_id".into(),format!("gr_000_{node}")),
                ("current_class".into(),"graph_repeat_node".into()),
                ("family_length_bp".into(),family.as_ref().map(|f|f.family_length_bp.to_string()).unwrap_or_else(||".".into())),
                ("graph_core_length_bp".into(),graph.segments[&node].sequence.len().to_string()),
                ("graph_template_length_bp".into(),binding.measurement_length().to_string()),
                ("policy_length_basis".into(),if family.is_some(){"complete_aligned_family"}else{"graph_template_exact_span"}.into()),
                ("graph_template_proof_sha256".into(),binding.proof_sha256.clone()),
                ("graph_template_reads_sha256".into(),binding.reads_sha256.clone()),
                ("graph_path_templates_sha256".into(),binding.path_templates_sha256.clone()),
                ("p1_count".into(),"26".into()),("p2_count".into(),"22".into()),("p3_count".into(),"22".into()),("p4_count".into(),"19".into()),("denominator".into(),"89".into()),
            ]));
            proofs.push_str(&format!("{id}\t{node}\t{}\t{}\t{}\t{}\t{}\t{}\n",binding.measurement_length(),binding.measurement_basis(),binding.proof_sha256,binding.reads_sha256,binding.path_templates_sha256,binding.evidence));
        }
        assert_eq!(rows.len(),1);
        let columns=rows[0].keys().cloned().collect::<Vec<_>>();
        fs::write(audit.join("canonical_repeat_pairs.tsv"),format!("{}\n{}",columns.join("\t"),rows.iter().map(|r|format!("{}\n",columns.iter().map(|c|r[c].as_str()).collect::<Vec<_>>().join("\t"))).collect::<String>())).unwrap();
        fs::write(audit.join("graph_template_bindings.tsv"),proofs).unwrap();
    }
    #[test]
    fn compound_source_no_action_execution_consumer_accepts_effective_initial_only() {
        let f=Fixture::new(false);let (bundle,c)=publish(&f);let audit=f.root.join("01_assess");
        write_context_audit(&f,&c,&audit);
        let options=Options::parse(&["--sample-bundle".into(),f.bundle.display().to_string(),"--reads".into(),f.component.component_reads.as_ref().unwrap().display().to_string(),"--out-dir".into(),f.root.display().to_string(),"--graph-measurement".into(),"multi-context".into()]).unwrap();
        assert!(!f.root.join("03_post_assess").exists());
        for status in ["no_change","review_required"] {
            repeat_auto::compound_test_completion(&options,&bundle,status).unwrap();
            repeat_auto::verify_graph_measurement(&f.root,GraphMeasurement::MultiContext).unwrap();
        }
        // A separately valid, freshly signed retained bundle cannot borrow the
        // normalized initial audit, even when its component identity is the same.
        let other=Fixture::new(false);
        repeat_auto::compound_test_completion(&options,&other.bundle,"no_change").unwrap();
        assert!(repeat_auto::verify_graph_measurement(&f.root,GraphMeasurement::MultiContext)
            .unwrap_err().to_string().contains("lacks its initial or retained assessment"));
        // Moving the identical effective bundle to an adoption endpoint still
        // requires a real final assessment; normalization is no substitute.
        let final_bundle=f.root.join("02_adopt/post_adopt_bundle.tsv");
        fs::create_dir(final_bundle.parent().unwrap()).unwrap();fs::copy(&bundle,&final_bundle).unwrap();
        repeat_auto::compound_test_completion(&options,&final_bundle,"confirmed").unwrap();
        assert!(repeat_auto::verify_graph_measurement(&f.root,GraphMeasurement::MultiContext)
            .unwrap_err().to_string().contains("lacks its initial or retained assessment"));
        repeat_auto::compound_test_completion(&options,&bundle,"no_change").unwrap();
        let before=fs::read(c.source_contract.as_ref().unwrap()).unwrap();
        repeat_auto::verify_graph_measurement(&f.root,GraphMeasurement::MultiContext).unwrap();
        assert_eq!(fs::read(c.source_contract.as_ref().unwrap()).unwrap(),before);
    }
