    fn actual_scope_fixture(graph:&str, fasta:&str, contract:&str, blast:&str)->Fixture {
        let mut f=Fixture::new(false);
        fs::write(&f.component.gfa,graph).unwrap();fs::write(&f.component.component_fasta,fasta).unwrap();fs::write(&f.blast,blast).unwrap();
        let value=|key:&str|contract.lines().find_map(|l|{let c=l.split('\t').collect::<Vec<_>>();(c.len()==4&&c[0]=="walk"&&c[2]==key).then(||c[3].to_string())}).unwrap();
        let walk=value("oriented_nodes");
        f.walk=walk.split(',').map(|v|PathStep{node:v[..v.len()-1].into(),reverse:v.ends_with('-')}).collect();
        f.reverse=value("reverse_complemented")=="true";
        f.offset=value("authority_offset0").parse().unwrap();
        fs::copy(&f.component.component_fasta,f.component.rotated_reference.as_ref().unwrap()).unwrap();
        fs::copy(&f.component.component_fasta,f.component.validate_data_dir.as_ref().unwrap().parent().unwrap().join("01.inputs/rotated_reference.fasta")).unwrap();
        f.contract();f
    }
